type verifiedMemoryMutations struct{ *memoryMutations }

func (mutations verifiedMemoryMutations) CommitHostMutationVerified(ctx context.Context, epoch uint64,
	kind authority.HostMutationKind, subject, operation string, expected uint64, payload []byte,
	verify func(context.Context) error,
) (uint64, error) {
	m := mutations.memoryMutations
	m.mu.Lock()
	defer m.mu.Unlock()
	key := m.key(kind, subject)
	if m.entries[key].Sequence != expected {
		return 0, authority.ErrConflict
	}
	if verify != nil {
		if err := verify(ctx); err != nil {
			return 0, err
		}
	}
	ack, err := m.js.Publish(ctx, "ts.control.gru.host."+string(kind)+"."+subject, payload)
	if err != nil {
		return 0, err
	}
	m.sequence = ack.Sequence
	m.entries[key] = authority.LogEntry{Kind: kind, SubjectKey: subject, OperationID: operation,
		Epoch: epoch, Sequence: m.sequence, Payload: bytes.Clone(payload)}
	return m.sequence, nil
}

func testNATSUserKey(node string) string {
	seed := sha256.Sum256([]byte("host-test-user:" + node))
	pair, err := nkeys.FromRawSeed(nkeys.PrefixByteUser, seed[:])
	if err != nil {
		panic(err)
	}
	defer pair.Wipe()
	public, err := pair.PublicKey()
	if err != nil {
		panic(err)
	}
	return public
}

func NewAgent(cfg AgentConfig) (*Agent, error) {
	for name, value := range map[string]string{"cell": cfg.Cell, "node": cfg.Node, "environment": cfg.Environment} {
		if err := validateToken(value, name); err != nil {
			return nil, err
		}
	}
	if cfg.TSAuthPort != 0 && (cfg.TSAuthPort < 1 || cfg.TSAuthPort > 65535) {
		return nil, errors.New("ts-auth port must be between 1 and 65535")
	}
	if cfg.Conn == nil || len(cfg.Identity) != ed25519.PrivateKeySize || len(cfg.ControllerPublicKey) != ed25519.PublicKeySize {
		return nil, errors.New("agent requires NATS connection, Ed25519 identity and pinned controller public key")
	}
	if !nkeys.IsValidPublicUserKey(cfg.NATSUserPublicKey) {
		return nil, errors.New("agent requires its authenticated NATS user public key")
	}
	if cfg.ClockCheck == nil {
		return nil, errors.New("agent requires a fresh host clock health check")
	}
	if len(cfg.Roles) == 0 || len(cfg.Roles) > 32 {
		return nil, errors.New("agent requires roles")
	}
	for i, role := range cfg.Roles {
		if err := validateToken(role, "role"); err != nil {
			return nil, err
		}
		if slices.Contains(cfg.Roles[:i], role) {
			return nil, errors.New("duplicate agent role")
		}
	}
	if err := ValidateWorkloadPaths(cfg.InstallRoot, cfg.StateRoot, cfg.WorkloadIdentity); err != nil {
		return nil, err
	}
	if err := ValidatePrivateHostState(cfg.StateRoot, cfg.Cell, cfg.Node); err != nil {
		return nil, err
	}
	if cfg.ManagedRuntimeRoot != "" {
		if !filepath.IsAbs(cfg.ManagedRuntimeRoot) || filepath.Clean(cfg.ManagedRuntimeRoot) != cfg.ManagedRuntimeRoot ||
			cfg.ManagedRuntimeRoot == cfg.InstallRoot || cfg.ManagedRuntimeRoot == cfg.StateRoot ||
			strings.HasPrefix(cfg.ManagedRuntimeRoot, cfg.InstallRoot+string(filepath.Separator)) ||
			strings.HasPrefix(cfg.ManagedRuntimeRoot, cfg.StateRoot+string(filepath.Separator)) ||
			strings.HasPrefix(cfg.InstallRoot, cfg.ManagedRuntimeRoot+string(filepath.Separator)) ||
			strings.HasPrefix(cfg.StateRoot, cfg.ManagedRuntimeRoot+string(filepath.Separator)) {
			return nil, errors.New("managed runtime root must be clean, absolute and separate from host roots")
		}
	}
	if cfg.TerraBaseRoot != "" {
		if err := validateTerraBaseRoot(cfg.TerraBaseRoot, cfg.InstallRoot, cfg.StateRoot, cfg.WorkloadIdentity); err != nil {
			return nil, err
		}
	}
	if cfg.TSAuthRoot != "" {
		if err := validateWorkloadRoot("ts-auth", cfg.TSAuthRoot, cfg.WorkloadIdentity, cfg.InstallRoot, cfg.StateRoot,
			cfg.TerraBaseRoot); err != nil {
			return nil, err
		}
	}
	for role, limit := range cfg.RoleMemoryMaxBytes {
		if !slices.Contains(cfg.Roles, role) || limit == 0 || validateCgroupMemoryMax(limit) != nil {
			return nil, fmt.Errorf("role %q memory cap must name a host role and be a nonzero page-aligned byte count", role)
		}
	}
	if cfg.TerraBaseDataVolume && cfg.TerraBaseRoot == "" {
		return nil, errors.New("a terrabase data volume needs a terrabase root")
	}
	if cfg.TerraBaseDataVolume && !strings.HasPrefix(cfg.TerraBaseDataVolumeID, "ocid1.volume.") {
		return nil, errors.New("a terrabase data volume needs its recorded volume OCID")
	}
	if cfg.PollInterval == 0 {
		cfg.PollInterval = 5 * time.Second
	}
	if cfg.PollInterval < 100*time.Millisecond {
		return nil, errors.New("agent poll interval is too short")
	}
	runner := cfg.Runner
	if runner == nil {
		runner = NewProcessRunner(filepath.Join(cfg.StateRoot, cfg.Cell, cfg.Node), cfg.WorkloadIdentity, cfg.Cell, cfg.Node)
	}
	id, err := randomID()
	if err != nil {
		return nil, err
	}
	return &Agent{cfg: cfg, runner: runner, processID: id, pending: make(map[string]pendingCycle),
		terraBase: make(map[string]terraBaseMember), nativeRoots: make(map[string]*managedNativeRoot)}, nil

func (a *Agent) Run(ctx context.Context) error {
	if err := a.runner.Recover(ctx); err != nil {
		return fmt.Errorf("recover native workloads: %w", err)
	}
	work, cancel := context.WithCancel(ctx)
	defer cancel()
	defer func() {
		stopCtx, stopCancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer stopCancel()
		_ = a.runner.Close(stopCtx)
	}()
	defer a.stopAllManagedNativeRoots()
	if err := a.checkClock(); err != nil {
		return err
	}
	if a.cfg.Initialized != nil {
		a.cfg.Initialized()
	}
	if err := a.waitForSession(work); err != nil {
		return err
	}
	lost := make(chan error, 1)
	go a.maintainSession(work, cancel, lost)
	if a.cfg.ManagedRuntimeRoot != "" {
		go a.refreshNativeRootPins(work)
	}
	go a.publishLoad(work)
	go a.publishLogs(work)
	if a.cfg.FollowRollouts != nil {
		go a.cfg.FollowRollouts(work, a)
	}
	if a.cfg.FollowNetBird != nil {
		go a.cfg.FollowNetBird(work, a)
	}
	ticker := time.NewTicker(a.cfg.PollInterval)
	defer ticker.Stop()
	type roleFailure struct {
		class string
		at    time.Time
	}
	failures := make(map[string]roleFailure)
	for {
		ctx := observability.StartTrace(ctx)
		for _, role := range a.cfg.Roles {
			if err := work.Err(); err != nil {
				break
			}
			if a.sessionLost.Load() {
				break
			}
			err := a.reconcile(work, role)
			if a.cfg.ManagedRuntimeRoot == "" || work.Err() != nil || a.sessionLost.Load() {
				continue
			}
			if err == nil {
				if _, failed := failures[role]; failed {
					slog.InfoContext(ctx, "managed host reconciliation recovered", "role", role)
					delete(failures, role)
				}
				continue
			}
			class := managedReconcileErrorClass(err)
			previous := failures[role]
			if class != previous.class || time.Since(previous.at) >= 10*time.Second {
				// A repeated cause is still logged, but only at DEBUG.
				level := slog.LevelDebug
				if class != previous.class {
					level = slog.LevelWarn
				}
				slog.Log(ctx, level, "managed host reconciliation deferred", "role", role, "cause_class", class)
				failures[role] = roleFailure{class: class, at: time.Now()}
			}
		}
		select {
		case err := <-lost:
			return err
		case <-ctx.Done():
			return ctx.Err()
		case <-work.Done():
			if a.sessionLost.Load() {
				// Session loss cancels work before workload shutdown finishes.
				// Wait for its reason so a supervisor sees a failed host.
				return <-lost
			}
			return work.Err()
		case <-ticker.C:
		}
	}
}

func (a *Agent) failSession(cancel context.CancelFunc, lost chan<- error, reason error) {
	a.sessionFailOnce.Do(func() { a.stopForLostSession(cancel, lost, reason) })
}

func (a *Agent) stopForLostSession(cancel context.CancelFunc, lost chan<- error, reason error) {
	a.sessionLost.Store(true)
	cancel()
	if err := a.stopAllManagedNativeRoots(); err != nil {
		reason = errors.Join(reason, err)
	}
	a.mu.RLock()
	accepted := a.session
	a.mu.RUnlock()
	if accepted.SessionID != "" && accepted.Epoch != 0 {
		cause := "renewal_failed"
		if errors.Is(reason, errSessionExecutionReserve) {
			cause = "reserve_exhausted"
		}
		digest := sha256.Sum256([]byte(accepted.SessionID))
		slog.Info("host session fenced", "session_id_hash", hex.EncodeToString(digest[:16]),
			"epoch", accepted.Epoch, "expires_at", accepted.ExpiresAt.UTC().Format(time.RFC3339Nano),
			"cause_class", cause)
	}
	stopCtx, stopCancel := context.WithTimeout(context.Background(), sessionExecutionReserve-time.Second)
	if err := a.runner.Close(stopCtx); err != nil {
		reason = errors.Join(reason, fmt.Errorf("stop native workloads after session loss: %w", err))
	}
	stopCancel()
	lost <- reason
}

type failingRecoverRunner struct{ *memoryRunner }

func (failingRecoverRunner) Recover(context.Context) error {
	return errors.New("ownership lock held")
}

func (a *Agent) makeRequest(operation string, payload any) (request, error) {
	data, err := json.Marshal(payload)
	if err != nil {
		return request{}, err
	}
	nonce, err := randomNonce()
	if err != nil {
		return request{}, err
	}
	a.mu.RLock()
	s := a.session
	a.mu.RUnlock()
	r := request{Version: 1, CredentialProtocol: 1, Node: a.cfg.Node, NATSUserPublicKey: a.cfg.NATSUserPublicKey, Operation: operation, SessionID: a.processID, Epoch: s.Epoch, Nonce: nonce, IssuedAt: time.Now().UTC(), Payload: data}
	if err := signRequest(&r, a.cfg.Identity, a.cfg.Cell); err != nil {
		return request{}, err
	}
	return r, nil
}

// sendToLeader builds, signs and sends a fresh request, and sends a new one
// when a follower controller denies it: every controller of the cell serves
// the host subjects, but only the authority leader answers effectful requests.
// It returns the request whose reply was accepted.
func (a *Agent) sendToLeader(ctx context.Context, operation string, payload, out any,
	signedOut *protocol.Envelope, prepare func(*request) error,
) (request, error) {
	for attempt := 1; ; attempt++ {
		r, err := a.makeRequest(operation, payload)
		if err != nil {
			return request{}, err
		}
		if prepare != nil {
			if err := prepare(&r); err != nil {
				return request{}, err
			}
		}
		err = exchangeWithEnvelope(ctx, a.cfg.Conn, a.cfg.Cell, a.cfg.ControllerPublicKey, r, out, signedOut)
		if !errors.Is(err, errControllerNotLeader) || attempt == leaderRequestAttempts {
			return r, err
		}
		select {
		case <-ctx.Done():
			return request{}, ctx.Err()
		case <-time.After(time.Duration(attempt) * leaderRetryBackoff):
		}
	}
}

func (a *Agent) acquire(ctx context.Context) error {
	if err := a.checkClock(); err != nil {
		return err
	}
	var s session
	if _, err := a.sendToLeader(ctx, "session", struct {
		Kind string `json:"kind"`
	}{"acquire"}, &s, nil, func(r *request) error {
		r.Epoch = 0
		return signRequest(r, a.cfg.Identity, a.cfg.Cell)
	}); err != nil {
		return fmt.Errorf("acquire host session: %w", err)
	}
	if s.SessionID != a.processID || s.Epoch == 0 {
		return errors.New("invalid acquired host session")
	}
	if err := a.acceptSession(s); err != nil {
		return err
	}
	a.logSessionAccepted("acquire", s)
	return nil
}

func (a *Agent) waitForSession(ctx context.Context) error {
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		if err := a.acquire(ctx); err == nil {
			a.sessionRecovered()
			return nil
		} else if !retrySessionExchange(err) && !errors.Is(err, errSessionOwned) {
			a.logSessionFailure("acquire", err, 0)
			return err
		} else {
			a.logSessionFailure("acquire", err, 0)
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

func retrySessionExchange(err error) bool {
	return errors.Is(err, errSessionBackendUnavailable) || errors.Is(err, errSessionContention) || transientSessionTransport(err)
}

func sessionUsableUntil(s session, now time.Time) bool {
	return now.Before(s.ExpiresAt.Add(-sessionExecutionReserve))
}

func (a *Agent) checkClock() error {
	if a.cfg.ClockCheck == nil {
		return errors.New("host clock health check is absent")
	}
	if err := a.cfg.ClockCheck(); err != nil {
		return fmt.Errorf("host clock is unhealthy: %w", err)
	}
	return nil
}

func (a *Agent) wallTime() time.Time {
	if a.wallNow != nil {
		return a.wallNow()
	}
	return time.Now()
}

func (a *Agent) acceptSession(s session) error {
	if err := a.checkClock(); err != nil {
		return err
	}
	receivedAt := time.Now()
	remaining := s.ExpiresAt.Sub(a.wallTime()) - sessionExecutionReserve
	if remaining <= 0 || remaining > sessionTTL-sessionExecutionReserve+maxClockSkew {
		return errors.New("signed host session has no execution reserve")
	}
	// receivedAt carries Go's monotonic reading. A later wall-clock step cannot
	// extend this locally bounded execution lease.
	deadline := receivedAt.Add(min(remaining, sessionTTL-sessionExecutionReserve))
	a.mu.Lock()
	a.session = s
	a.sessionSafeUntil = deadline
	a.mu.Unlock()
	return nil
}

func (a *Agent) executionLease() (session, time.Time, error) {
	if err := a.checkClock(); err != nil {
		return session{}, time.Time{}, err
	}
	a.mu.RLock()
	s, deadline := a.session, a.sessionSafeUntil
	a.mu.RUnlock()
	if deadline.IsZero() || !time.Now().Before(deadline) || !sessionUsableUntil(s, a.wallTime()) {
		return session{}, time.Time{}, errSessionExecutionReserve
	}
	return s, deadline, nil
}

func (a *Agent) maintainSession(ctx context.Context, cancel context.CancelFunc, lost chan<- error) {
	a.maintainSessionLease(ctx, func(reason error) { a.failSession(cancel, lost, reason) })
}

func (a *Agent) maintainSessionLease(ctx context.Context, fail func(error)) {
	watchCtx, stopWatch := context.WithCancel(ctx)
	watchDone := make(chan struct{})
	go func() {
		defer close(watchDone)
		ticks := a.watchdogTicks
		if ticks == nil {
			ticker := time.NewTicker(time.Second)
			defer ticker.Stop()
			ticks = ticker.C
		}
		for {
			select {
			case <-watchCtx.Done():
				return
			case <-ticks:
				if _, _, err := a.executionLease(); err != nil {
					fail(err)
					return
				}
			}
		}
	}()
	defer func() {
		stopWatch()
		<-watchDone
	}()
	ticker := time.NewTicker(time.Second)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		current, deadline, err := a.executionLease()
		if err != nil {
			fail(err)
			return
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
		current, deadline, err = a.executionLease()
		if err != nil {
			fail(err)
			return
		}
		var next session
		renewCtx, renewCancel := context.WithDeadline(ctx, deadline)
		_, err = a.sendToLeader(renewCtx, "session", struct {
			Kind string `json:"kind"`
		}{"renew"}, &next, nil, nil)
		renewCancel()
		if err == nil {
			if next.SessionID != current.SessionID || next.Epoch != current.Epoch || !next.ExpiresAt.After(current.ExpiresAt) {
				err = errors.New("renewed session binding mismatch")
			} else if _, _, err = a.executionLease(); err == nil {
				if err = a.acceptSession(next); err == nil {
					a.logSessionAccepted("renew", next)
				}
			}
		}
		_, _, leaseErr := a.executionLease()
		if leaseErr != nil {
			fail(leaseErr)
			return
		}
		if err != nil && retrySessionExchange(err) {
			a.logSessionFailure("renew", err, time.Until(deadline))
			continue
		}
		if err != nil {
			a.logSessionFailure("renew", err, time.Until(deadline))
			fail(fmt.Errorf("host session renewal failed: %w", err))
			return
		}
		a.sessionRecovered()
	}
}

func (a *Agent) logSessionAccepted(phase string, accepted session) {
	digest := sha256.Sum256([]byte(accepted.SessionID))
	slog.Info("host session accepted", "phase", phase,
		"session_id_hash", hex.EncodeToString(digest[:16]), "epoch", accepted.Epoch,
		"expires_at", accepted.ExpiresAt.UTC().Format(time.RFC3339Nano))
}

func (a *Agent) failSession(cancel context.CancelFunc, lost chan<- error, reason error) {
	a.sessionFailOnce.Do(func() { a.stopForLostSession(cancel, lost, reason) })
}

func (a *Agent) stopForLostSession(cancel context.CancelFunc, lost chan<- error, reason error) {
	a.sessionLost.Store(true)
	cancel()
	if err := a.stopAllManagedNativeRoots(); err != nil {
		reason = errors.Join(reason, err)
	}
	a.mu.RLock()
	accepted := a.session
	a.mu.RUnlock()
	if accepted.SessionID != "" && accepted.Epoch != 0 {
		cause := "renewal_failed"
		if errors.Is(reason, errSessionExecutionReserve) {
			cause = "reserve_exhausted"
		}
		digest := sha256.Sum256([]byte(accepted.SessionID))
		slog.Info("host session fenced", "session_id_hash", hex.EncodeToString(digest[:16]),
			"epoch", accepted.Epoch, "expires_at", accepted.ExpiresAt.UTC().Format(time.RFC3339Nano),
			"cause_class", cause)
	}
	stopCtx, stopCancel := context.WithTimeout(context.Background(), sessionExecutionReserve-time.Second)
	if err := a.runner.Close(stopCtx); err != nil {
		reason = errors.Join(reason, fmt.Errorf("stop native workloads after session loss: %w", err))
	}
	stopCancel()
	lost <- reason
}

func (a *Agent) request(ctx context.Context, operation string, payload, out any) error {
	_, err := a.sendToLeader(ctx, operation, payload, out, nil, nil)
	return err
}

func (a *Agent) VerifyOwnRegistration(registration Registration, controllerPublic ed25519.PublicKey) error {
	if a == nil || a.sessionLost.Load() || len(a.cfg.Identity) != ed25519.PrivateKeySize ||
		len(controllerPublic) != ed25519.PublicKeySize || !bytes.Equal(a.cfg.ControllerPublicKey, controllerPublic) {
		return errors.New("ownhost agent has no current pinned controller identity")
	}
	current, _, err := a.executionLease()
	if err != nil {
		return err
	}
	if registration.Cell != a.cfg.Cell || registration.Node != a.cfg.Node || registration.Environment != a.cfg.Environment ||
		registration.Generation != current.RegistrationGeneration ||
		registration.PublicKey != base64.StdEncoding.EncodeToString(a.cfg.Identity.Public().(ed25519.PublicKey)) ||
		registration.NATSUserPublicKey != a.cfg.NATSUserPublicKey {
		return errors.New("registration differs from the actual ownhost session and keys")
	}
	return nil
}

// HostRuntimeIdentity retains the existing authenticated Agent principal.
type HostRuntimeIdentity struct {
	identity   executionwire.WorkerIdentity
	controller ed25519.PublicKey
	deadline   time.Time
}

func (i HostRuntimeIdentity) Identity() executionwire.WorkerIdentity { return i.identity }
func (i HostRuntimeIdentity) ExpiresAt() time.Time                   { return i.deadline }
func (i HostRuntimeIdentity) ControllerPublicKey() ed25519.PublicKey {
	return slices.Clone(i.controller)
}

// RuntimeWorkerIdentity binds the local worker to the actual live host session.
func (a *Agent) RuntimeWorkerIdentity(instanceID, nodeID string) (HostRuntimeIdentity, error) {
	if a.sessionLost.Load() {
		return HostRuntimeIdentity{}, errors.New("host session was lost")
	}
	current, deadline, err := a.executionLease()
	if err != nil {
		return HostRuntimeIdentity{}, err
	}
	identity := executionwire.WorkerIdentity{
		Cell: a.cfg.Cell, HostNode: a.cfg.Node, NATSUserPublicKey: a.cfg.NATSUserPublicKey,
		HostPublicKey: base64.StdEncoding.EncodeToString(a.cfg.Identity.Public().(ed25519.PublicKey)),
		HostSessionID: a.processID, RegistrationGeneration: current.RegistrationGeneration,
		InstanceID: instanceID, NodeID: nodeID,
	}
	return HostRuntimeIdentity{identity: identity, controller: slices.Clone(a.cfg.ControllerPublicKey), deadline: deadline}, nil
}

func (a *Agent) executionLease() (session, time.Time, error) {
	if err := a.checkClock(); err != nil {
		return session{}, time.Time{}, err
	}
	a.mu.RLock()
	s, deadline := a.session, a.sessionSafeUntil
	a.mu.RUnlock()
	if deadline.IsZero() || !time.Now().Before(deadline) || !sessionUsableUntil(s, a.wallTime()) {
		return session{}, time.Time{}, errSessionExecutionReserve
	}
	return s, deadline, nil
}

func ValidateWorkloadPaths(installRoot, stateRoot string, identity WorkloadIdentity) error {
	if identity.UID == 0 || identity.GID == 0 {
		return errors.New("host workload_uid and workload_gid must be nonzero")
	}
	if !filepath.IsAbs(installRoot) || !filepath.IsAbs(stateRoot) ||
		filepath.Clean(installRoot) != installRoot || filepath.Clean(stateRoot) != stateRoot {
		return errors.New("agent installation and state roots must be clean absolute paths")
	}
	if installRoot == string(filepath.Separator) || stateRoot == string(filepath.Separator) {
		return errors.New("agent installation and state roots cannot be the filesystem root")
	}
	if installRoot == stateRoot || strings.HasPrefix(installRoot, stateRoot+string(filepath.Separator)) ||
		strings.HasPrefix(stateRoot, installRoot+string(filepath.Separator)) {
		return errors.New("agent installation and state roots must not overlap")
	}
	if err := inspectWorkloadPath(filepath.Dir(installRoot), identity, true, false, false); err != nil {
		return fmt.Errorf("install root parent: %w", err)
	}
	if err := inspectWorkloadPath(installRoot, identity, false, true, false); err != nil {
		return fmt.Errorf("install root: %w", err)
	}
	if info, err := os.Lstat(installRoot); err == nil {
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok || owner.Uid != uint32(os.Geteuid()) || info.Mode().Perm()&0022 != 0 {
			return errors.New("install root must be supervisor-owned and not tenant-writable")
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("inspect install root: %w", err)
	}
	if err := inspectWorkloadPath(stateRoot, identity, false, true, true); err != nil {
		return fmt.Errorf("state root: %w", err)
	}
	if err := inspectPrivateStateDirectory(stateRoot); err != nil {
		return err
	}
	return nil
}

// ValidatePrivateHostState checks the host-owned state subtree before the
// runtime probe. Missing descendants are created privately by the runner.
func ValidatePrivateHostState(stateRoot, cell, node string) error {
	for name, value := range map[string]string{"cell": cell, "node": node} {
		if err := validateToken(value, name); err != nil {
			return err
		}
	}
	for _, path := range []string{stateRoot, filepath.Join(stateRoot, cell), filepath.Join(stateRoot, cell, node)} {
		if err := inspectPrivateStateDirectory(path); err != nil {
			return err
		}
	}
	return nil
}

func inspectPrivateStateDirectory(path string) error {
	info, err := os.Lstat(path)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("inspect state directory: %w", err)
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 ||
		owner.Uid != uint32(os.Geteuid()) || info.Mode().Perm()&0077 != 0 {
		return fmt.Errorf("state directory %s must be private and supervisor-owned", path)
	}
	return nil
}

func inspectWorkloadPath(path string, identity WorkloadIdentity, tenantTraverse, allowMissing, privateState bool) error {
	current := string(filepath.Separator)
	for _, part := range strings.Split(strings.TrimPrefix(path, current), current) {
		if part != "" {
			current = filepath.Join(current, part)
		}
		info, err := os.Lstat(current)
		if err != nil {
			if allowMissing && errors.Is(err, os.ErrNotExist) {
				return nil
			}
			return fmt.Errorf("inspect %s: %w", current, err)
		}
		if !info.IsDir() || info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("%s must be a directory without symlinks", current)
		}
		owner, ok := info.Sys().(*syscall.Stat_t)
		if !ok {
			return fmt.Errorf("cannot inspect owner of %s", current)
		}
		if os.Geteuid() == 0 && owner.Uid != 0 {
			return fmt.Errorf("host path ancestor %s must be root-owned", current)
		}
		permissions := info.Mode().Perm()
		search := permissions & 0001
		write := permissions & 0002
		if owner.Gid == identity.GID {
			search, write = permissions&0010, permissions&0020
		}
		if owner.Uid == identity.UID {
			search, write = permissions&0100, permissions&0200
		}
		if tenantTraverse && search == 0 {
			return fmt.Errorf("workload identity cannot traverse %s", current)
		}
		if privateState && os.Geteuid() == 0 && permissions&0022 != 0 {
			return fmt.Errorf("state path ancestor %s is group- or world-writable", current)
		}
		if identity.UID != uint32(os.Geteuid()) && write != 0 &&
			(privateState || info.Mode()&os.ModeSticky == 0 || owner.Uid != 0) {
			return fmt.Errorf("workload identity can replace host path under %s", current)
		}
	}
	return nil
}

func (a *Agent) fetchArtifact(ctx context.Context, role, digest string) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Minute)
	defer cancel()
	root := filepath.Join(a.cfg.InstallRoot, role, "sha256-"+digest)
	path := filepath.Join(root, role)
	for _, directory := range []string{a.cfg.InstallRoot, filepath.Join(a.cfg.InstallRoot, role), root} {
		if err := ensureInstallDirectory(directory, a.cfg.WorkloadIdentity.GID); err != nil {
			return "", err
		}
	}
	if valid, err := verifyInstalledArtifact(path, digest, a.cfg.WorkloadIdentity.GID); err != nil {
		return "", err
	} else if valid {
		return path, nil
	}
	tmp, err := os.CreateTemp(root, "partial-*")
	if err != nil {
		return "", err
	}
	defer os.Remove(tmp.Name())
	defer tmp.Close()
	hash := sha256.New()
	var offset, total int64
	for {
		ctx := observability.StartTrace(ctx)
		var part artifactReply
		if err := a.request(ctx, "artifact", artifactQuery{Role: role, Digest: digest, Offset: offset, Length: artifactChunkBytes}, &part); err != nil {
			if errors.Is(err, errArtifactPreparing) || errors.Is(err, errSessionContention) {
				select {
				case <-ctx.Done():
					return "", ctx.Err()
				case <-time.After(250 * time.Millisecond):
					continue
				}
			}
			return "", err
		}
		if part.Digest != digest || part.Offset != offset || part.Total <= 0 || part.Total > maxArtifactBytes || len(part.Data) == 0 || len(part.Data) > artifactChunkBytes || offset+int64(len(part.Data)) > part.Total || total != 0 && part.Total != total {
			return "", errors.New("artifact chunk binding mismatch")
		}
		total = part.Total
		if _, err := tmp.Write(part.Data); err != nil {
			return "", err
		}
		if _, err := hash.Write(part.Data); err != nil {
			return "", err
		}
		offset += int64(len(part.Data))
		if offset == total {
			break
		}
	}
	if hex.EncodeToString(hash.Sum(nil)) != digest {
		return "", errors.New("artifact SHA-256 mismatch")
	}
	if err := tmp.Chown(-1, int(a.cfg.WorkloadIdentity.GID)); err != nil {
		return "", err
	}
	if err := tmp.Chmod(0550); err != nil {
		return "", err
	}
	if err := tmp.Sync(); err != nil {
		return "", err
	}
	if err := tmp.Close(); err != nil {
		return "", err
	}
	if err := os.Rename(tmp.Name(), path); err != nil {
		return "", err
	}
	dir, err := os.Open(root)
	if err != nil {
		return "", err
	}
	defer dir.Close()
	if err := dir.Sync(); err != nil {
		return "", err
	}
	return path, nil
}

func ensureInstallDirectory(path string, gid uint32) error {
	if err := os.Mkdir(path, 0710); err != nil && !errors.Is(err, os.ErrExist) {
		return fmt.Errorf("create install directory %s: %w", path, err)
	}
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.IsDir() || info.Mode()&os.ModeSymlink != 0 || owner.Uid != uint32(os.Geteuid()) ||
		info.Mode().Perm()&0022 != 0 {
		return fmt.Errorf("install directory %s must be supervisor-owned and not tenant-writable", path)
	}
	if owner.Gid != gid {
		if err := os.Chown(path, -1, int(gid)); err != nil {
			return fmt.Errorf("set install directory group: %w", err)
		}
	}
	if err := os.Chmod(path, 0710); err != nil {
		return fmt.Errorf("set install directory mode: %w", err)
	}
	return nil
}

func verifyInstalledArtifact(path, digest string, gid uint32) (bool, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("open installed artifact: %w", err)
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return false, err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !ok || !info.Mode().IsRegular() || owner.Uid != uint32(os.Geteuid()) ||
		info.Mode().Perm()&0022 != 0 || info.Mode()&(os.ModeSetuid|os.ModeSetgid|os.ModeSticky) != 0 {
		return false, errors.New("installed artifact must be a supervisor-owned, non-writable regular file")
	}
	hash := sha256.New()
	if _, err := io.Copy(hash, io.LimitReader(file, maxArtifactBytes+1)); err != nil {
		return false, err
	}
	if info.Size() > maxArtifactBytes || hex.EncodeToString(hash.Sum(nil)) != digest {
		return false, nil
	}
	if owner.Gid != gid {
		if err := file.Chown(-1, int(gid)); err != nil {
			return false, err
		}
	}
	if err := file.Chmod(0550); err != nil {
		return false, err
	}
	return true, nil
}

func (c *Controller) readArtifactChunk(ctx context.Context, digest string, offset int64, length int) ([]byte, int64, error) {
	return c.readCachedArtifact(ctx, &c.workloadCache, maxArtifactBytes, digest, offset, length)
}

func (c *Controller) readCachedArtifact(ctx context.Context, cache *artifactCache, maxBytes int64, digest string, offset int64, length int) ([]byte, int64, error) {
	if err := ctx.Err(); err != nil {
		return nil, 0, err
	}
	c.cacheMu.Lock()
	defer c.cacheMu.Unlock()
	if c.cacheClosed {
		return nil, 0, errors.New("artifact cache is closed")
	}
	if cache.digest != digest || cache.file == nil {
		if !cache.downloading && !time.Now().Before(cache.retryAfter) {
			cache.downloading = true
			go c.downloadArtifact(cache, maxBytes, digest)
		}
		return nil, 0, errArtifactPreparing
	}
	if offset < 0 || offset >= cache.size {
		return nil, 0, errors.New("artifact offset is outside object")
	}
	count := min(int64(length), cache.size-offset)
	data := make([]byte, count)
	if _, err := cache.file.ReadAt(data, offset); err != nil {
		return nil, 0, err
	}
	return data, cache.size, nil
}

func (c *Controller) downloadArtifact(cache *artifactCache, maxBytes int64, digest string) {
	ctx, cancel := context.WithTimeout(c.cacheContext, 2*time.Minute)
	defer cancel()
	var downloaded *os.File
	var size int64
	var fetchErr error
	defer func() {
		c.cacheMu.Lock()
		defer c.cacheMu.Unlock()
		cache.downloading = false
		if c.cacheClosed || fetchErr != nil {
			if downloaded != nil {
				_ = downloaded.Close()
			}
			if fetchErr != nil {
				cache.retryAfter = time.Now().Add(3 * time.Second)
			}
			return
		}
		if cache.file != nil {
			_ = cache.file.Close()
		}
		cache.file = downloaded
		cache.digest = digest
		cache.size = size
	}()
	info, err := c.artifacts.GetInfo(ctx, "sha256-"+digest)
	if err != nil {
		fetchErr = err
		return
	}
	if info == nil || info.Deleted || info.Opts != nil && info.Opts.Link != nil || info.Size == 0 || info.Size > uint64(maxBytes) {
		fetchErr = errors.New("artifact metadata is invalid")
		return
	}
	js, err := jetstream.New(c.conn)
	if err != nil {
		fetchErr = err
		return
	}
	file, err := os.CreateTemp("", "ts-host-artifact-*")
	if err != nil {
		fetchErr = err
		return
	}
	_ = os.Remove(file.Name())
	downloaded = file
	if err := artifact.ReadVerified(ctx, js, c.artifacts, info.Bucket, "sha256-"+digest,
		digest, int64(info.Size), maxBytes, file); err != nil {
		fetchErr = err
		return
	}
	if err := file.Sync(); err != nil {
		fetchErr = err
		return
	}
	size = int64(info.Size)
}

func (c *Controller) closeCache() {
	c.cacheCancel()
	c.cacheMu.Lock()
	defer c.cacheMu.Unlock()
	c.cacheClosed = true
	for _, cache := range []*artifactCache{&c.workloadCache, &c.netbirdCache} {
		if cache.file != nil {
			_ = cache.file.Close()
			cache.file = nil
		}
	}
}

func ReadVerified(ctx context.Context, js jetstream.JetStream, store interface {
	GetInfo(context.Context, string, ...jetstream.GetObjectInfoOpt) (*jetstream.ObjectInfo, error)
}, bucket, name, digest string, signedSize, maxBytes int64, dst io.Writer) error {
	if js == nil || store == nil || dst == nil || signedSize <= 0 || signedSize > maxBytes || len(digest) != 64 {
		return fmt.Errorf("%w: reader arguments", ErrInvalid)
	}
	info, err := store.GetInfo(ctx, name)
	if err != nil {
		return fmt.Errorf("inspect artifact: %w", err)
	}
	if err := validateMetadata(info, bucket, name, signedSize); err != nil {
		return err
	}
	stream, err := js.Stream(ctx, "OBJ_"+bucket)
	if err != nil {
		return fmt.Errorf("bind artifact readback stream: %w", err)
	}
	return verifyChunks(ctx, info, bucket, digest, signedSize, dst, func(ctx context.Context, sequence uint64, subject string) (*jetstream.RawStreamMsg, error) {
		return stream.GetMsg(ctx, sequence, jetstream.WithGetMsgSubject(subject))
	})
}

func validateMetadata(info *jetstream.ObjectInfo, bucket, name string, signedSize int64) error {
	if info == nil || info.Name != name || info.Bucket != bucket || info.Deleted ||
		info.Opts != nil && info.Opts.Link != nil || info.Size != uint64(signedSize) ||
		info.NUID == "" || info.Chunks == 0 || uint64(info.Chunks) > uint64(signedSize) {
		return fmt.Errorf("%w: artifact object metadata", ErrInvalid)
	}
	return nil
}

func verifyChunks(ctx context.Context, info *jetstream.ObjectInfo, bucket, digest string, sizeLimit int64, dst io.Writer,
	get func(context.Context, uint64, string) (*jetstream.RawStreamMsg, error)) error {
	if info == nil || info.NUID == "" || info.Chunks == 0 || sizeLimit <= 0 ||
		uint64(info.Chunks) > uint64(sizeLimit) {
		return fmt.Errorf("%w: artifact chunk metadata", ErrInvalid)
	}
	storedDigest, err := jetstream.DecodeObjectDigest(info.Digest)
	if err != nil || len(storedDigest) != sha256.Size {
		return fmt.Errorf("%w: artifact object digest", ErrInvalid)
	}
	subject := "$O." + bucket + ".C." + info.NUID
	h := sha256.New()
	var size int64
	sequence := uint64(1)
	for range info.Chunks {
		if err := ctx.Err(); err != nil {
			return err
		}
		message, err := get(ctx, sequence, subject)
		if errors.Is(err, jetstream.ErrMsgNotFound) {
			return fmt.Errorf("artifact chunk is not visible: %w", jetstream.ErrObjectNotFound)
		}
		if err != nil {
			return fmt.Errorf("read artifact chunk: %w", err)
		}
		if message == nil || message.Subject != subject || message.Sequence < sequence ||
			message.Sequence == ^uint64(0) || len(message.Data) == 0 || int64(len(message.Data)) > sizeLimit-size {
			return fmt.Errorf("%w: artifact chunk sequence or size", ErrInvalid)
		}
		if _, err := dst.Write(message.Data); err != nil {
			return fmt.Errorf("spool artifact chunk: %w", err)
		}
		_, _ = h.Write(message.Data)
		size += int64(len(message.Data))
		sequence = message.Sequence + 1
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	extra, err := get(ctx, sequence, subject)
	if err == nil || extra != nil {
		return fmt.Errorf("%w: artifact has extra chunks", ErrInvalid)
	}
	if !errors.Is(err, jetstream.ErrMsgNotFound) {
		return fmt.Errorf("check artifact chunk count: %w", err)
	}
	actual := h.Sum(nil)
	if size != sizeLimit || hex.EncodeToString(actual) != digest || !bytes.Equal(actual, storedDigest) {
		return fmt.Errorf("%w: artifact bytes differ from signed digest", ErrInvalid)
	}
	return nil
}

func Touch(ctx context.Context, js nats.JetStreamContext, bucket, name string) error {
	subject := metaSubject(bucket, name)
	meta, err := liveMeta(ctx, js, bucket, subject, name)
	if err != nil {
		return err
	}
	err = publishMeta(ctx, js, subject, meta.Data, meta.Sequence)
	if !errors.Is(err, ErrChanged) {
		return err
	}
	// Another write since the read fences a collector just the same,
	// unless it deleted the object.
	_, err = liveMeta(ctx, js, bucket, subject, name)
	return err
}

// liveMeta reads an object's metadata from the stream leader and refuses a
// deleted object.
func liveMeta(ctx context.Context, js nats.JetStreamContext, bucket, subject, name string) (*nats.RawStreamMsg, error) {
	meta, err := js.GetLastMsg("OBJ_"+bucket, subject, nats.Context(ctx))
	if errors.Is(err, nats.ErrMsgNotFound) {
		return nil, jetstream.ErrObjectNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("read artifact metadata: %w", err)
	}
	var info jetstream.ObjectInfo
	if err := json.Unmarshal(meta.Data, &info); err != nil || info.Name != name {
		return nil, fmt.Errorf("%w: artifact object metadata", ErrInvalid)
	}
	if info.Deleted {
		return nil, jetstream.ErrObjectNotFound
	}
	return meta, nil
}

// DeleteIfUnchanged deletes the object whose metadata is meta, as nats.go
// does, but only while meta is still the subject's last message: a Touch
// since then refuses it with ErrChanged. It then purges the object's chunks.
func DeleteIfUnchanged(ctx context.Context, js nats.JetStreamContext, bucket string, meta *nats.RawStreamMsg) error {
	var info jetstream.ObjectInfo
	if meta == nil || json.Unmarshal(meta.Data, &info) != nil || info.NUID == "" || info.Deleted ||
		meta.Subject != metaSubject(bucket, info.Name) {
		return fmt.Errorf("%w: artifact object metadata", ErrInvalid)
	}
	info.Deleted = true
	info.Size, info.Chunks, info.Digest, info.ModTime = 0, 0, "", time.Time{}
	data, err := json.Marshal(info)
	if err != nil {
		return err
	}
	if err := publishMeta(ctx, js, meta.Subject, data, meta.Sequence); err != nil {
		return err
	}
	if err := js.PurgeStream("OBJ_"+bucket, &nats.StreamPurgeRequest{Subject: "$O." + bucket + ".C." + info.NUID}, nats.Context(ctx)); err != nil {
		return fmt.Errorf("purge deleted artifact chunks: %w", err)
	}
	return nil
}

func metaSubject(bucket, name string) string {
	return "$O." + bucket + ".M." + base64.URLEncoding.EncodeToString([]byte(name))
}

func publishMeta(ctx context.Context, js nats.JetStreamContext, subject string, data []byte, sequence uint64) error {
	msg := nats.NewMsg(subject)
	msg.Header.Set(nats.MsgRollup, nats.MsgRollupSubject)
	msg.Data = data
	_, err := js.PublishMsg(msg, nats.Context(ctx), nats.ExpectLastSequencePerSubject(sequence))
	if apiErr, ok := errors.AsType[*nats.APIError](err); ok && (apiErr.ErrorCode == nats.JSErrCodeStreamWrongLastSequence ||
		apiErr.ErrorCode == nats.JSErrCodeStreamWrongLastSequenceConstant) {
		return ErrChanged
	}
	return err
}

func validateContainerMaterial(files ContainerMaterialFiles) error {
	uid, gid, split := strings.Cut(files.User, ":")
	u, ue := strconv.ParseUint(uid, 10, 32)
	g, ge := strconv.ParseUint(gid, 10, 32)
	if !split || ue != nil || ge != nil || u == 0 || g == 0 || !time.Now().Before(files.ExpiresAt) ||
		(!files.CredentialExpiresAt.IsZero() && (!files.CredentialExpiresAt.After(time.Now()) || files.ExpiresAt.After(files.CredentialExpiresAt))) ||
		len(files.Files) > vaultsecret.MaxRefs || len(files.Files) != len(files.FileEnvironment) {
		return errors.New("container material inventory, user or expiry is invalid")
	}
	total := 0
	seen := make(map[string]bool, len(files.Files))
	for key, name := range files.FileEnvironment {
		value, found := files.Files[name]
		if !containerMaterialKey.MatchString(key) || name != strings.ToLower(key) || path.Base(name) != name ||
			!found || seen[name] || len(value) == 0 || len(value) > 64<<10 {
			return errors.New("container material requires distinct signed file environment bindings")
		}
		total += len(value)
		seen[name] = true
	}
	if total > 96<<10 {
		return errors.New("container material exceeds the bounded secret inventory")
	}
	return nil
}

type hostStateStatusError struct {
	jetstream.KeyValue
	err error
}

func (state hostStateStatusError) Status(ctx context.Context) (jetstream.KeyValueStatus, error) {
	if state.err != nil {
		return nil, state.err
	}
	return state.KeyValue.Status(ctx)
}

type hostStateProvisioner struct {
	jetstream.JetStream
	statusError error
}

func (js hostStateProvisioner) CreateOrUpdateKeyValue(ctx context.Context, cfg jetstream.KeyValueConfig) (jetstream.KeyValue, error) {
	state, err := js.JetStream.CreateOrUpdateKeyValue(ctx, cfg)
	if err != nil {
		return nil, err
	}
	return hostStateStatusError{KeyValue: state, err: js.statusError}, nil
}

func NewController(ctx context.Context, cfg ControllerConfig) (*Controller, error) {
	if err := validateToken(cfg.Cell, "cell"); err != nil {
		return nil, err
	}
	if cfg.Conn == nil || cfg.JS == nil || cfg.Artifacts == nil || cfg.HostMutations == nil || len(cfg.ResponseKey) != ed25519.PrivateKeySize {
		return nil, errors.New("controller requires NATS, JetStream, ordered host mutations, artifact store and Ed25519 response key")
	}
	if cfg.AuthorityEpoch == nil || cfg.AuthorityGuard == nil {
		return nil, errors.New("controller requires authority epoch and guard")
	}
	managedEffectGate := cfg.ManagedEffectGate
	if managedEffectGate == nil {
		if gate, ok := cfg.HostMutations.(interface {
			BeginActiveWorkloadEffect(context.Context, uint64, authority.WorkloadScope) (func(), error)
		}); ok {
			managedEffectGate = gate.BeginActiveWorkloadEffect
		}
	}
	if cfg.ManagedRegistrationVerifier != nil && managedEffectGate == nil {
		return nil, errors.New("managed host registration requires a terminal effect gate")
	}
	replicas := cfg.StateReplicas
	if replicas == 0 {
		replicas = 3
	}
	if replicas < 1 || replicas > 5 {
		return nil, errors.New("invalid host state replica count")
	}
	state := cfg.State
	if state == nil {
		var err error
		state, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: stateBucket, History: 2, MaxValueSize: 64 << 10, MaxBytes: 256 << 20, Storage: jetstream.FileStorage, Replicas: replicas})
		if err != nil {
			return nil, fmt.Errorf("open host state: %w", err)
		}
	}
	status, err := state.Status(ctx)
	if err != nil {
		if cfg.State == nil && errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect host state: %w", ErrStateNotReady, err)
		}
		return nil, err
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("host state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	if err := rejectObsoleteRetirementState(ctx, state, cfg.Cell); err != nil {
		return nil, err
	}
	controlLog := cfg.ControlLog
	if controlLog == nil {
		controlLog, err = cfg.JS.Stream(ctx, "TS_CONTROL_LOG")
		if err != nil {
			return nil, fmt.Errorf("open ordered control log: %w", err)
		}
	}
	cacheCtx, cacheCancel := context.WithCancel(context.Background())
	return &Controller{cell: cfg.Cell, conn: cfg.Conn, state: state, controlLog: controlLog, mutations: cfg.HostMutations,
		managedVerifier: cfg.ManagedRegistrationVerifier, managedDesiredVerifier: cfg.ManagedDesiredVerifier,
		managedEffectGate: managedEffectGate, materialProvider: cfg.ManagedMaterialProvider,
		credentialFloor: cfg.ManagedCredentialFloor, volumeInspector: cfg.ManagedVolumeInspector, runtimeEffects: cfg.RuntimeEffects,
		containerMaterial: cfg.ContainerMaterialProvider, registryAdmission: cfg.RegistryAdmissionProvider,
		taskLoadRoles:    cfg.TaskLoadRoles,
		functionMaterial: cfg.FunctionMaterialProvider,
		terraBaseCA:      cfg.TerraBaseCA, roleIdentity: cfg.RoleIdentity, nodeAddress: cfg.NodeAddress, restartGate: cfg.RestartGate, artifacts: cfg.Artifacts, responseKey: cfg.ResponseKey, ready: make(chan struct{}),
		authorityEpoch: cfg.AuthorityEpoch, authorityGuard: cfg.AuthorityGuard, authorityLeader: cfg.AuthorityLeader,
		cacheContext: cacheCtx, cacheCancel: cacheCancel}, nil
}

func (c *Controller) guard(ctx context.Context, epoch uint64) error {
	if c.authorityGuard == nil {
		return nil
	}
	if epoch == 0 || c.authorityEpoch() != epoch {
		return fmt.Errorf("%w: host authority epoch is stale", authority.ErrFenced)
	}
	return c.authorityGuard(ctx, epoch)
}

func sessionKey(cell, node string) string       { return "session." + cell + "." + node }
func desiredKey(cell, node, role string) string { return "desired." + cell + "." + node + "." + role }
func reportKey(cell, node, role string) string  { return "report." + cell + "." + node + "." + role }
func cycleKey(cell, node, role string) string   { return "cycle." + cell + "." + node + "." + role }

func (c *Controller) get(ctx context.Context, key string, destination any) (uint64, bool, error) {
	if c.conn != nil {
		return c.readLeaderState(ctx, key, destination)
	}
	// Only package tests construct a Controller without the connection required
	// by NewController and NewReader.
	entry, err := c.state.Get(ctx, key)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return 0, false, nil
	}
	if err != nil {
		return 0, false, err
	}
	if entry.Operation() != jetstream.KeyValuePut {
		return 0, false, errors.New("host state has a tombstone")
	}
	if err := decodeStrict(entry.Value(), destination); err != nil {
		return 0, false, fmt.Errorf("corrupt host state %s: %w", key, err)
	}
	return entry.Revision(), true, nil
}

func (c *Controller) cas(ctx context.Context, key string, value any, revision uint64) (uint64, error) {
	data, err := json.Marshal(value)
	if err != nil {
		return 0, err
	}
	if len(data) > 64<<10 {
		return 0, errors.New("host state value too large")
	}
	if revision == 0 {
		return c.state.Create(ctx, key, data)
	}
	return c.state.Update(ctx, key, data, revision)
}

// sessionSnapshot uses the stream leader because KV.Get can read a lagging
// replica when the bucket has direct reads enabled.
func (c *Controller) sessionSnapshot(ctx context.Context, key string) (session, uint64, bool, error) {
	if c.sessionRead != nil {
		return c.sessionRead(ctx, key)
	}
	return c.readLeaderSession(ctx, key)
}

func (c *Controller) readLeaderSession(ctx context.Context, key string) (session, uint64, bool, error) {
	var s session
	revision, exists, err := c.readLeaderState(ctx, key, &s)
	return s, revision, exists, err
}

func (c *Controller) reportSnapshot(ctx context.Context, key string) (Report, uint64, bool, error) {
	var report Report
	revision, exists, err := c.readLeaderState(ctx, key, &report)
	return report, revision, exists, err
}

func (c *Controller) readLeaderState(ctx context.Context, key string, destination any) (uint64, bool, error) {
	if c.conn == nil { // Only package tests construct a controller without Conn.
		return c.get(ctx, key, destination)
	}
	js, err := c.conn.JetStream()
	if err != nil {
		return 0, false, err
	}
	subject := "$KV." + stateBucket + "." + key
	msg, err := js.GetLastMsg("KV_"+stateBucket, subject, nats.Context(ctx))
	if errors.Is(err, nats.ErrMsgNotFound) {
		return 0, false, nil
	}
	if err != nil {
		return 0, false, err
	}
	if msg == nil || msg.Subject != subject || msg.Sequence == 0 {
		return 0, false, errors.New("invalid host state")
	}
	if operation := msg.Header.Get("KV-Operation"); operation != "" {
		if operation == "DEL" || operation == "PURGE" {
			return 0, false, nil
		}
		return 0, false, errors.New("invalid host state operation")
	}
	if marker := msg.Header.Get(jetstream.MarkerReasonHeader); marker != "" {
		if marker == "MaxAge" || marker == "Purge" || marker == "Remove" {
			return 0, false, nil
		}
		return 0, false, errors.New("invalid host state marker")
	}
	if len(msg.Data) > 64<<10 {
		return 0, false, errors.New("invalid host state")
	}
	if err := decodeStrict(msg.Data, destination); err != nil {
		return 0, false, fmt.Errorf("corrupt host state %s: %w", key, err)
	}
	return msg.Sequence, true, nil
}

func (c *Controller) Run(ctx context.Context) error {
	var subscriptions []*nats.Subscription
	unsubscribe := func() {
		for _, sub := range subscriptions {
			_ = sub.Unsubscribe()
		}
		subscriptions = nil
	}
	defer func() {
		unsubscribe()
		c.closeCache()
	}()
	ticker := time.NewTicker(hostLeaderPoll)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		leader := c.authorityLeader == nil || c.authorityLeader()
		if leader && subscriptions == nil {
			var err error
			if subscriptions, err = c.subscribeHostRequests(ctx); err != nil {
				return err
			}
		} else if !leader && subscriptions != nil {
			unsubscribe()
		}
		c.readyOnce.Do(func() { close(c.ready) })
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}
	}
}

func (c *Controller) subscribeHostRequests(ctx context.Context) ([]*nats.Subscription, error) {
	subscriptions := make([]*nats.Subscription, 0, len(hostOperations))
	for _, operation := range hostOperations {
		sub, err := c.conn.QueueSubscribe(protocol.AgentObservation(c.cell, "*", operation), "host-controller-"+operation, func(msg *nats.Msg) { c.handle(ctx, msg) })
		if err == nil {
			subscriptions = append(subscriptions, sub)
			continue
		}
		for _, existing := range subscriptions {
			_ = existing.Unsubscribe()
		}
		return nil, err
	}
	flushCtx, flushCancel := context.WithTimeout(ctx, 5*time.Second)
	err := c.conn.FlushWithContext(flushCtx)
	flushCancel()
	if err != nil {
		for _, sub := range subscriptions {
			_ = sub.Unsubscribe()
		}
		return nil, fmt.Errorf("flush host subscriptions: %w", err)
	}
	return subscriptions, nil
}

func (c *Controller) handle(parent context.Context, msg *nats.Msg) {
	if msg.Reply == "" || len(msg.Data) > 64<<10 {
		return
	}
	deadline := 4 * time.Second
	if len(msg.Data) > 0 && (strings.Contains(msg.Subject, ".material") || strings.Contains(msg.Subject, ".function-material") ||
		strings.Contains(msg.Subject, ".drain-command") || strings.Contains(msg.Subject, ".drain-result") ||
		strings.Contains(msg.Subject, ".backup-command") || strings.Contains(msg.Subject, ".backup-result") ||
		strings.Contains(msg.Subject, ".volume-init") || strings.HasSuffix(msg.Subject, ".runtime-effect") || strings.HasSuffix(msg.Subject, ".container-material") || strings.HasSuffix(msg.Subject, ".registry-admission")) {
		deadline = 30 * time.Second
	}
	ctx, cancel := context.WithTimeout(observability.ContinueTrace(parent, msg.Header.Get("traceparent")), deadline)
	defer cancel()
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(msg.Data, &envelope, 64<<10); err != nil {
		return
	}
	var req request
	if err := protocol.DecodeStrict([]byte(envelope.Payload), &req, 64<<10); err != nil {
		return
	}
	req.Envelope = envelope
	var materialDeadline time.Time
	if req.Operation == "container-material" {
		materialDeadline = (ContainerMaterialEvidence{Request: envelope}).Deadline()
		ctx, cancel = context.WithDeadline(ctx, materialDeadline)
		defer cancel()
	}
	expectedSubject, err := protocol.AgentObservationSubject(c.cell, req.NATSUserPublicKey, req.Operation)
	if err != nil || expectedSubject != msg.Subject || envelope.Actor != req.Node || envelope.Kind != "host."+req.Operation {
		return
	}
	registration, err := c.registration(ctx, req.Node)
	if err != nil || registration.NATSUserPublicKey != req.NATSUserPublicKey {
		return
	}
	result := response{Nonce: req.Nonce, Node: req.Node, SessionID: req.SessionID, Epoch: req.Epoch, Operation: req.Operation}
	var payload any
	switch req.Operation {
	case "session":
		payload, err = c.handleSession(ctx, req)
	case "desired", "artifact", "cycle", "report", "material", "function-material", "drain-command", "drain-result", "backup-command", "backup-result", "volume-init", "load", "terrabase-peer", "terrabase-format", "runtime-effect", "container-material", "registry-admission",
		"role-identity", "rollout", "rollout-binary", "netbird", "netbird-binary":
		payload, err = c.handleAuthorized(ctx, req)
	default:
		err = errors.New("unknown host operation")
	}
	if err != nil {
		result.Error = err.Error()
		if req.Operation == "session" {
			result.Retryable = transientSessionTransport(err) || errors.Is(err, errSessionContention)
		} else {
			result.Retryable = errors.Is(err, errArtifactPreparing) || errors.Is(err, errSessionContention)
		}
	} else if payload != nil {
		result.Payload, _ = json.Marshal(payload)
	}
	if req.Operation == "container-material" {
		if reply, ok := payload.(containerMaterialReply); ok {
			materialDeadline = containerMaterialDeadline(materialDeadline, reply.InventoryExpiresAt)
		}
		if ctx.Err() != nil || !time.Now().Before(materialDeadline) {
			return
		}
	}
	data, err := protocol.EncodeJSON(result)
	if err != nil {
		return
	}
	issued := time.Now().UTC()
	expires := issued.Add(requestTTL)
	if req.Operation == "container-material" {
		expires = containerMaterialDeadline(expires, materialDeadline)
	}
	signed, err := protocol.SignEnvelope(data, protocol.EnvelopeScope{Region: c.cell, Kind: "host.response." + req.Operation, Actor: "controller", OperationID: entityid.Derive("host-request", req.Nonce), Epoch: req.Epoch}, issued, expires, c.responseKey)
	if err != nil {
		return
	}
	wire, err := protocol.EncodeJSON(signed)
	if err != nil {
		return
	}
	if req.Operation == "container-material" && (ctx.Err() != nil || !time.Now().Before(materialDeadline)) {
		return
	}
	_ = msg.Respond(wire)
}

func (c *Controller) registration(ctx context.Context, node string) (Registration, error) {
	r, _, exists, err := c.readRegistration(ctx, node)
	if err != nil {
		return Registration{}, err
	}
	if !exists {
		return Registration{}, errors.New("host is not registered")
	}
	return r, nil
}

func (c *Controller) handleSession(ctx context.Context, req request) (payload any, resultErr error) {
	stage := "decode"
	defer func() {
		if resultErr != nil {
			c.logSessionFailure(stage, resultErr)
		}
	}()
	var operation struct {
		Kind string `json:"kind"`
	}
	if err := decodeStrict(req.Payload, &operation); err != nil {
		return nil, err
	}
	stateKey := sessionKey(c.cell, req.Node)
	for attempt := range 8 {
		stage = "registration"
		r, err := c.registration(ctx, req.Node)
		if err != nil {
			return nil, err
		}
		key, err := decodePublicKey(r.PublicKey)
		if err != nil {
			return nil, err
		}
		stage = "verify"
		if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
			return nil, err
		}
		if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
			return nil, err
		}
		now := time.Now().UTC()
		stage = "session_read"
		old, revision, exists, err := c.sessionSnapshot(ctx, stateKey)
		if err != nil {
			return nil, err
		}
		if exists && exactSessionReplay(old, r, req, operation.Kind, now) {
			stage = "session_write"
			if _, err := c.cas(ctx, stateKey, old, revision); err == nil {
				return old, nil
			} else if casConflict(err) {
				if err := waitSessionConflict(ctx, attempt); err != nil {
					return nil, err
				}
				continue
			} else {
				return nil, err
			}
		}
		var next session
		stage = "session_validate"
		switch operation.Kind {
		case "acquire":
			if req.Epoch != 0 {
				return nil, errors.New("acquire requires epoch zero")
			}
			if exists && sessionHeld(old, r, now) {
				return nil, errSessionOwned
			}
			next = session{RegistrationGeneration: r.Generation, SessionID: req.SessionID, Epoch: 1, ExpiresAt: req.IssuedAt.Add(sessionTTL), LastNonce: req.Nonce, LastIssuedAt: req.IssuedAt}
			if exists {
				if old.Epoch == ^uint64(0) {
					return nil, errors.New("session epoch exhausted")
				}
				next.Epoch = old.Epoch + 1
			}
		case "renew":
			if !exists || !renewableSession(old, r, req, now) {
				return nil, errors.New("session is no longer renewable")
			}
			next = old
			next.ExpiresAt = req.IssuedAt.Add(sessionTTL)
			next.LastNonce = req.Nonce
			next.LastIssuedAt = req.IssuedAt
		default:
			return nil, errors.New("unknown session operation")
		}
		stage = "session_write"
		written, err := c.cas(ctx, stateKey, next, revision)
		if err == nil && written > 0 {
			return next, nil
		}
		if !casConflict(err) {
			return nil, err
		}
		if err := waitSessionConflict(ctx, attempt); err != nil {
			return nil, err
		}
	}
	stage = "registration"
	r, err := c.registration(ctx, req.Node)
	if err != nil {
		return nil, err
	}
	key, err := decodePublicKey(r.PublicKey)
	if err != nil {
		return nil, err
	}
	stage = "verify"
	if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
		return nil, err
	}
	stage = "session_read"
	old, revision, exists, err := c.sessionSnapshot(ctx, stateKey)
	if err != nil {
		return nil, err
	}
	now := time.Now().UTC()
	if exists && exactSessionReplay(old, r, req, operation.Kind, now) {
		stage = "session_write"
		if _, err := c.cas(ctx, stateKey, old, revision); err == nil {
			return old, nil
		} else if !casConflict(err) {
			return nil, err
		}
		return nil, errSessionContention
	}
	stage = "session_validate"
	switch operation.Kind {
	case "acquire":
		if req.Epoch != 0 {
			return nil, errors.New("acquire requires epoch zero")
		}
		if exists && sessionHeld(old, r, now) {
			return nil, errSessionOwned
		}
	case "renew":
		if !exists || !renewableSession(old, r, req, now) {
			return nil, errors.New("session is no longer renewable")
		}
	default:
		return nil, errors.New("unknown session operation")
	}
	return nil, errSessionContention
}

func exactSessionReplay(old session, r Registration, req request, kind string, now time.Time) bool {
	replayEpoch := kind == "acquire" && req.Epoch == 0 || kind == "renew" && req.Epoch == old.Epoch
	return replayEpoch && old.RegistrationGeneration == r.Generation && old.SessionID == req.SessionID &&
		old.LastNonce == req.Nonce && old.LastIssuedAt.Equal(req.IssuedAt) && now.Before(old.ExpiresAt)
}

func sessionHeld(old session, r Registration, now time.Time) bool {
	return now.Before(old.ExpiresAt) && (old.RegistrationGeneration == r.Generation || r.ManagedOCI == nil)
}

func renewableSession(old session, r Registration, req request, now time.Time) bool {
	return old.RegistrationGeneration == r.Generation && old.SessionID == req.SessionID && old.Epoch == req.Epoch &&
		now.Before(old.ExpiresAt) && req.IssuedAt.After(old.LastIssuedAt)
}

func currentAuthorizedSession(s session, r Registration, req request, now time.Time) bool {
	return s.RegistrationGeneration == r.Generation && s.SessionID == req.SessionID && s.Epoch == req.Epoch &&
		now.Before(s.ExpiresAt) && !req.IssuedAt.Before(s.LastIssuedAt.Add(-requestTTL))
}

func (c *Controller) authorize(ctx context.Context, req request) (Registration, session, error) {
	stateKey := sessionKey(c.cell, req.Node)
	for attempt := range 8 {
		r, err := c.registration(ctx, req.Node)
		if err != nil {
			return Registration{}, session{}, err
		}
		key, err := decodePublicKey(r.PublicKey)
		if err != nil {
			return Registration{}, session{}, err
		}
		if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
			return Registration{}, session{}, err
		}
		if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
			return Registration{}, session{}, err
		}
		s, revision, exists, err := c.sessionSnapshot(ctx, stateKey)
		if err != nil {
			return Registration{}, session{}, err
		}
		if !exists || !currentAuthorizedSession(s, r, req, time.Now()) {
			return Registration{}, session{}, errors.New("host session is not current")
		}
		if _, err := c.cas(ctx, stateKey, s, revision); err == nil {
			return r, s, nil
		} else if !casConflict(err) {
			return Registration{}, session{}, fmt.Errorf("host session changed: %w", err)
		}
		if err := waitSessionConflict(ctx, attempt); err != nil {
			return Registration{}, session{}, err
		}
	}
	r, err := c.registration(ctx, req.Node)
	if err != nil {
		return Registration{}, session{}, err
	}
	key, err := decodePublicKey(r.PublicKey)
	if err != nil {
		return Registration{}, session{}, err
	}
	if err := verifyRequest(req, key, c.cell, time.Now().UTC()); err != nil {
		return Registration{}, session{}, err
	}
	if err := c.verifyCredentialProtocol(ctx, req, r); err != nil {
		return Registration{}, session{}, err
	}
	s, _, exists, err := c.sessionSnapshot(ctx, stateKey)
	if err != nil {
		return Registration{}, session{}, err
	}
	if !exists || !currentAuthorizedSession(s, r, req, time.Now()) {
		return Registration{}, session{}, errors.New("host session is not current")
	}
	return Registration{}, session{}, errSessionContention
}

var errSessionContention = errors.New("session contention")

func waitSessionConflict(ctx context.Context, attempt int) error {
	timer := time.NewTimer(time.Duration(attempt+1) * 2 * time.Millisecond)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

func (c *Controller) verifyCredentialProtocol(ctx context.Context, request request, registration Registration) error {
	if registration.ManagedPlacement == nil || c.credentialFloor == nil {
		return nil
	}
	generation, err := c.credentialFloor(ctx, registration)
	if err != nil || generation == 0 {
		return errors.New("managed credential floor is unavailable")
	}
	if generation > 1 && request.CredentialProtocol < 1 {
		return errors.New("host credential protocol cannot enforce the committed generation")
	}
	return nil
}

func (c *Controller) handleAuthorized(ctx context.Context, req request) (payload any, resultErr error) {
	r, s, err := c.authorize(ctx, req)
	if err != nil {
		return nil, err
	}
	epoch := c.authorityEpoch()
	if err := c.guard(ctx, epoch); err != nil {
		return nil, err
	}
	requireActive := req.Operation == "material" || req.Operation == "container-material" || req.Operation == "registry-admission" || req.Operation == "function-material"
	if req.Operation == "runtime-effect" {
		var operation struct {
			Action string `json:"action"`
		}
		if err := json.Unmarshal(req.Payload, &operation); err != nil {
			return nil, err
		}
		requireActive = operation.Action != "close"
	}
	defer func() {
		if resultErr != nil {
			return
		}
		if err := c.recheckReplyAuthority(ctx, epoch, req, r, requireActive); err != nil {
			payload, resultErr = nil, err
		}
	}()
	switch req.Operation {
	case "desired":
		registration, registrationRevision, exists, err := c.readRegistration(ctx, req.Node)
		if err != nil {
			return nil, err
		}
		if !exists || !sameJSON(registration, r) || registration.Generation != s.RegistrationGeneration {
			return nil, errors.New("host registration changed during desired request")
		}
		var query struct {
			Role string `json:"role"`
		}
		if err := decodeStrict(req.Payload, &query); err != nil {
			return nil, err
		}
		if !slices.Contains(r.Roles, query.Role) {
			return nil, errors.New("role is not registered")
		}
		desired, revision, exists, err := c.readDesired(ctx, req.Node, query.Role)
		if err != nil {
			return nil, err
		}
		if !exists {
			return desiredReply{Registration: &registration, RegistrationRevision: registrationRevision}, nil
		}
		return desiredReply{Desired: &desired, Revision: revision, Registration: &registration, RegistrationRevision: registrationRevision}, nil
	case "artifact":
		return c.serveArtifact(ctx, req, r)
	case "material":
		return c.serveMaterial(ctx, req, r, s)
	case "function-material":
		return c.serveFunctionMaterial(ctx, req, r, s)
	case "volume-init":
		return c.serveVolumeInit(ctx, req, r, s)
	case "runtime-effect":
		return c.serveRuntimeEffect(ctx, req, r, s)
	case "container-material":
		return c.serveContainerMaterial(ctx, req, r, s)
	case "registry-admission":
		return c.serveRegistryAdmission(ctx, req, r, s)
	case "drain-command":
		return c.serveManagedDrainCommand(ctx, req, r)
	case "drain-result":
		return c.storeManagedDrainResult(ctx, req, r)
	case "backup-command":
		return c.serveManagedBackupCommand(ctx, req, r)
	case "backup-result":
		return c.storeManagedBackupResult(ctx, req, r)
	case "cycle":
		return c.serveCycle(ctx, req, r, s)
	case "report":
		return c.storeReport(ctx, req, r, s)
	case "load":
		return c.storeLoad(ctx, req, r)
	case "rollout", "rollout-binary":
		return c.serveRollout(ctx, req, r)
	case "netbird", "netbird-binary":
		return c.serveNetBird(ctx, req, r)
	case "terrabase-peer":
		return c.serveTerraBasePeer(ctx, req, r)
	case "terrabase-format":
		return c.serveTerraBaseFormat(ctx, req, r)
	case "role-identity":
		return c.serveRoleIdentity(ctx, req, r)
	}
	return nil, errors.New("unknown host operation")
}

func (c *Controller) serveArtifact(ctx context.Context, req request, r Registration) (any, error) {
	var query artifactQuery
	if err := decodeStrict(req.Payload, &query); err != nil {
		return nil, err
	}
	if !slices.Contains(r.Roles, query.Role) || validateDigest(query.Digest) != nil || query.Offset < 0 || query.Length < 1 || query.Length > artifactChunkBytes {
		return nil, errors.New("invalid artifact query")
	}
	d, _, exists, err := c.readDesired(ctx, req.Node, query.Role)
	if err != nil {
		return nil, err
	}
	if !exists || d.Withdrawn || d.Digest != query.Digest {
		return nil, errors.New("artifact is not desired for this host")
	}
	data, total, err := c.readArtifactChunk(ctx, query.Digest, query.Offset, query.Length)
	if err != nil {
		return nil, err
	}
	current, _, exists, err := c.readDesired(ctx, req.Node, query.Role)
	if err != nil {
		return nil, err
	}
	if !exists || current.Withdrawn || current.Digest != query.Digest || current.Generation != d.Generation || current.AuthorityEpoch != d.AuthorityEpoch {
		return nil, errors.New("artifact target changed")
	}
	if _, _, err := c.authorize(ctx, req); err != nil {
		return nil, err
	}
	return artifactReply{Digest: query.Digest, Offset: query.Offset, Total: total, Data: data}, nil
}

func (c *Controller) recheckReplyAuthority(ctx context.Context, epoch uint64, req request, registration Registration, requireActive bool) error {
	latest, err := c.registration(ctx, req.Node)
	if err != nil || !sameJSON(registration, latest) {
		return errors.New("host registration changed while handling request")
	}
	key, err := decodePublicKey(latest.PublicKey)
	if err != nil || verifyRequest(req, key, c.cell, time.Now().UTC()) != nil {
		return errors.New("host request expired while handling request")
	}
	active, _, exists, err := c.sessionSnapshot(ctx, sessionKey(c.cell, req.Node))
	if err != nil {
		return err
	}
	if !exists || !currentAuthorizedSession(active, latest, req, time.Now()) {
		return errors.New("host session changed while handling request")
	}
	if requireActive {
		retired, err := c.retired(ctx, req.Node)
		if err != nil {
			return err
		}
		if retired {
			return errors.New("retired host cannot receive current material or runtime authority")
		}
	}
	if err := c.verifyCredentialProtocol(ctx, req, latest); err != nil {
		return err
	}
	return c.guard(ctx, epoch)
}

func (c *Controller) Register(ctx context.Context, r Registration) (Receipt, error) {
	id := entityid.Derive("host", r.Cell, r.Node)
	if r.ID != "" && r.ID != id {
		return Receipt{}, errors.New("host ID differs from its node identity")
	}
	r.ID = id
	if err := validateRegistration(r, c.cell); err != nil {
		return Receipt{}, err
	}
	if r.ManagedOCI != nil && r.ManagedPlacement == nil {
		return Receipt{}, errors.New("managed host registration requires current schema-3 placement pins")
	}
	authorityEpoch := c.authorityEpoch()
	if err := c.guard(ctx, authorityEpoch); err != nil {
		return Receipt{}, err
	}
	if r.ManagedMember != nil {
		if c.managedEffectGate == nil || r.ManagedPlacement == nil {
			return Receipt{}, errors.New("managed host registration requires a terminal effect gate and placement scope")
		}
		release, err := c.managedEffectGate(ctx, authorityEpoch, authority.WorkloadScope{
			DatabaseID: r.ManagedPlacement.DatabaseID, PartitionID: r.ManagedPlacement.PartitionID,
		})
		if err != nil {
			return Receipt{}, err
		}
		defer release()
	}
	c.registrationMu.Lock()
	defer c.registrationMu.Unlock()
	payload, operationID, err := mutationPayload(r)
	if err != nil {
		return Receipt{}, err
	}
	key := registrationSubjectKey(c.cell, r.Node)
	for range 8 {
		if r.ManagedMember != nil {
			if c.managedVerifier == nil {
				return Receipt{}, errors.New("managed host registration requires a current placement verifier")
			}
			if err := c.managedVerifier.VerifyManagedRegistration(ctx, r); err != nil {
				return Receipt{}, fmt.Errorf("verify managed host registration: %w", err)
			}
			if err := c.requireExclusiveManagedMember(ctx, r); err != nil {
				return Receipt{}, err
			}
		}
		current, revision, exists, err := c.readRegistration(ctx, r.Node)
		if err != nil {
			return Receipt{}, err
		}
		if exists {
			if (current.ManagedOCI == nil) != (r.ManagedOCI == nil) ||
				current.ManagedOCI != nil && (current.ManagedMember == nil || *current.ManagedOCI != *r.ManagedOCI ||
					*current.ManagedMember != *r.ManagedMember || current.FailureDomain != r.FailureDomain) {
				return Receipt{}, errors.New("host managed binding cannot be retargeted")
			}
			if r.Generation < current.Generation {
				return Receipt{}, errors.New("registration generation moved backward")
			}
			if r.Generation == current.Generation {
				if !sameJSON(r, current) {
					return Receipt{}, errors.New("registration changed without a generation increase")
				}
				return Receipt{r.Generation, revision}, nil
			}
		}
		if err := c.guard(ctx, authorityEpoch); err != nil {
			return Receipt{}, err
		}
		written, err := c.mutations.CommitHostMutation(ctx, authorityEpoch, authority.MutationRegistration, key, operationID, revision, payload)
		if err == nil {
			return Receipt{r.Generation, written}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return Receipt{}, err
		}
	}
	return Receipt{}, errors.New("registration contention")
}

func (c *Controller) ApplyDesired(ctx context.Context, d Desired) (Receipt, error) {
	if err := c.guard(ctx, d.AuthorityEpoch); err != nil {
		return Receipt{}, err
	}
	c.retireMu.RLock()
	defer c.retireMu.RUnlock()
	if !d.Withdrawn {
		retired, err := c.retired(ctx, d.Node)
		if err != nil {
			return Receipt{}, err
		}
		if retired {
			return Receipt{}, fmt.Errorf("%w: %s", ErrHostRetiring, d.Node)
		}
	}
	r, _, exists, err := c.readRegistration(ctx, d.Node)
	if err != nil {
		return Receipt{}, err
	}
	if !exists {
		return Receipt{}, errors.New("host is not registered")
	}
	if err := validateDesired(d, c.cell, r); err != nil {
		return Receipt{}, err
	}
	if d.ManagedMember != nil && !d.Withdrawn {
		if c.managedEffectGate == nil || r.ManagedPlacement == nil || c.managedDesiredVerifier == nil {
			return Receipt{}, errors.New("managed desired requires a terminal effect gate, placement scope and durable verifier")
		}
		release, err := c.managedEffectGate(ctx, d.AuthorityEpoch, authority.WorkloadScope{
			DatabaseID: r.ManagedPlacement.DatabaseID, PartitionID: r.ManagedPlacement.PartitionID,
		})
		if err != nil {
			return Receipt{}, err
		}
		defer release()
	}
	bucket := ""
	if !d.Withdrawn {
		info, err := c.artifacts.GetInfo(ctx, "sha256-"+d.Digest)
		if err != nil {
			return Receipt{}, err
		}
		if info.Deleted || info.Opts != nil && info.Opts.Link != nil || info.Size == 0 || info.Size > maxArtifactBytes {
			return Receipt{}, errors.New("artifact is absent, linked or outside size limit")
		}
		bucket = info.Bucket
	}
	payload, operationID, err := mutationPayload(d)
	if err != nil {
		return Receipt{}, err
	}
	key := desiredSubjectKey(c.cell, d.Node, d.Role)
	for range 8 {
		currentRegistration, _, registered, err := c.readRegistration(ctx, d.Node)
		if err != nil {
			return Receipt{}, err
		}
		if !registered || validateDesired(d, c.cell, currentRegistration) != nil {
			return Receipt{}, errors.New("registration changed before desired commit")
		}
		current, revision, exists, err := c.readDesired(ctx, d.Node, d.Role)
		if err != nil {
			return Receipt{}, err
		}
		if exists {
			if (current.ManagedMember == nil) != (d.ManagedMember == nil) {
				return Receipt{}, fmt.Errorf("%w: managed desired kind changed", ErrDesiredConflict)
			}
			if current.ManagedMember != nil && d.ManagedMember != nil &&
				(current.ManagedMember.Member != d.ManagedMember.Member || current.ManagedMember.OCI != d.ManagedMember.OCI ||
					current.ManagedMember.VolumeID != d.ManagedMember.VolumeID || current.ManagedMember.AttachmentID != d.ManagedMember.AttachmentID) {
				return Receipt{}, fmt.Errorf("%w: managed member or attachment retargeted", ErrDesiredConflict)
			}
			if d.AuthorityEpoch < current.AuthorityEpoch || d.Generation < current.Generation {
				return Receipt{}, fmt.Errorf("%w: generation or epoch moved backward", ErrDesiredConflict)
			}
			if d.Generation == current.Generation {
				if !sameDesiredTarget(d, current) {
					return Receipt{}, fmt.Errorf("%w: target changed within a generation", ErrDesiredConflict)
				}
				if d.AuthorityEpoch == current.AuthorityEpoch {
					return Receipt{d.Generation, revision}, nil
				}
			}
		}
		// The artifact collector deletes only metadata nobody touched since
		// it chose the artifact, so it cannot delete the bytes this desired
		// is about to name.
		if bucket != "" && c.conn != nil {
			js, err := c.conn.JetStream()
			if err != nil {
				return Receipt{}, err
			}
			if err := artifact.Touch(ctx, js, bucket, "sha256-"+d.Digest); err != nil {
				return Receipt{}, fmt.Errorf("pin desired artifact: %w", err)
			}
		}
		if err := c.guard(ctx, d.AuthorityEpoch); err != nil {
			return Receipt{}, err
		}
		var written uint64
		if d.ManagedMember != nil && !d.Withdrawn {
			verified, ok := c.mutations.(authority.VerifiedHostMutationStore)
			if !ok {
				return Receipt{}, errors.New("managed desired mutation store lacks a final verifier fence")
			}
			verify := func(verifyCtx context.Context) error {
				return c.managedDesiredVerifier(verifyCtx, d, currentRegistration, current, exists)
			}
			written, err = verified.CommitHostMutationVerified(ctx, d.AuthorityEpoch, authority.MutationDesired,
				key, operationID, revision, payload, verify)
		} else {
			written, err = c.mutations.CommitHostMutation(ctx, d.AuthorityEpoch, authority.MutationDesired,
				key, operationID, revision, payload)
		}
		if err == nil {
			return Receipt{d.Generation, written}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return Receipt{}, err
		}
	}
	return Receipt{}, errors.New("desired contention")
}

func validateRegistration(r Registration, cell string) error {
	if r.ID != "" && !entityid.Valid(r.ID) {
		return errors.New("host ID must be a canonical ULID")
	}
	if r.Cell != cell {
		return errors.New("registration belongs to another cell")
	}
	for name, value := range map[string]string{"cell": r.Cell, "node": r.Node, "environment": r.Environment} {
		if err := validateToken(value, name); err != nil {
			return err
		}
	}
	if r.ManagedOCI != nil {
		if err := validateManagedOCIBinding(*r.ManagedOCI, r.FailureDomain); err != nil {
			return err
		}
		if !strings.EqualFold(r.ManagedOCI.Region, cell) {
			return errors.New("managed OCI region is not this cell's region")
		}
		if r.ManagedMember == nil || r.SystemReserveBytes <= 0 || r.Capacity.MemoryBytes <= 0 ||
			r.Capacity.MemoryBytes > math.MaxInt64-r.SystemReserveBytes ||
			len(r.Roles) != 1 || r.Roles[0] != "terrabase" {
			return errors.New("managed host requires one terrabase role, member binding and signed memory reserve")
		}
		// Stored pre-schema-3 registrations remain readable for inspection;
		// Controller.Register separately requires these pins for admission.
		if r.ManagedPlacement != nil {
			if err := validateManagedPlacementBinding(*r.ManagedPlacement); err != nil {
				return err
			}
		}
		if err := validateManagedMemberBinding(*r.ManagedMember); err != nil {
			return err
		}
	} else if r.FailureDomain != "" {
		if err := validateToken(r.FailureDomain, "failure domain"); err != nil {
			return err
		}
	}
	if r.ManagedOCI == nil && (r.ManagedPlacement != nil || r.ManagedMember != nil || r.SystemReserveBytes != 0) {
		return errors.New("generic host cannot carry managed placement, member or memory reserve")
	}
	if r.TerraBaseDataVolumeID != "" && (r.ManagedOCI != nil || !slices.Contains(r.Roles, "terrabase") ||
		!strings.HasPrefix(r.TerraBaseDataVolumeID, "ocid1.volume.") || strings.ContainsAny(r.TerraBaseDataVolumeID, " \t\r\n/\\")) {
		return errors.New("C# terrabase data volume binding needs a volume OCID and terrabase role")
	}
	if r.Generation == 0 || len(r.Roles) == 0 || len(r.Roles) > 32 {
		return errors.New("invalid registration generation or roles")
	}
	seen := make(map[string]bool, len(r.Roles))
	for _, role := range r.Roles {
		if err := validateToken(role, "role"); err != nil {
			return err
		}
		if seen[role] {
			return errors.New("duplicate role")
		}
		seen[role] = true
	}
	if _, err := decodePublicKey(r.PublicKey); err != nil {
		return err
	}
	if !nkeys.IsValidPublicUserKey(r.NATSUserPublicKey) {
		return errors.New("registration NATS user public key is invalid")
	}
	if r.Capacity.CPU < 0 || r.Capacity.MemoryBytes < 0 || r.Capacity.DiskBytes < 0 {
		return errors.New("negative host capacity")
	}
	return nil
}

func validateDesired(d Desired, cell string, r Registration) error {
	if d.Cell != cell || d.Node != r.Node || d.Environment != r.Environment {
		return errors.New("desired identity mismatch")
	}
	if err := validateToken(d.Role, "role"); err != nil {
		return err
	}
	if !slices.Contains(r.Roles, d.Role) {
		return errors.New("role is not registered")
	}
	if (r.ManagedOCI == nil) != (d.ManagedMember == nil) {
		return errors.New("managed desired and registration kind differ")
	}
	if d.ManagedMember != nil {
		if r.ManagedMember == nil {
			return errors.New("managed registration lacks member binding")
		}
		if d.Role != "terrabase" || *r.ManagedOCI != d.ManagedMember.OCI ||
			*r.ManagedMember != d.ManagedMember.Member {
			return errors.New("managed desired binding differs from registration")
		}
		if err := validateManagedMemberLaunch(*d.ManagedMember, d, r); err != nil {
			return err
		}
	}
	if d.Generation == 0 {
		return errors.New("desired generation must be positive")
	}
	if d.Withdrawn {
		if d.Digest != "" || len(d.Args) != 0 || len(d.Env) != 0 || len(d.Secrets) != 0 {
			return errors.New("withdrawn desired contains execution data")
		}
	} else if err := validateDigest(d.Digest); err != nil {
		return err
	}
	if len(d.Args) > 64 || len(d.Env) > 64 {
		return errors.New("too many workload arguments or environment variables")
	}
	for _, arg := range d.Args {
		if len(arg) > 4096 {
			return errors.New("argument too long")
		}
	}
	for key, value := range d.Env {
		if !regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`).MatchString(key) || len(value) > 4096 {
			return errors.New("invalid workload environment")
		}
	}
	// A C# TerraBase member's environment is host-owned: it takes only
	// secret files, whose paths the host sets.
	for key := range d.Secrets {
		if d.Role == terrabase.Role && !vaultsecret.FileKey(key) {
			return errors.New("terrabase takes only Vault secret files (keys ending in _FILE)")
		}
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	for key := range d.Env {
		if roleidentity.Reserved(d.Role, key) {
			return fmt.Errorf("the host sets %s for %s's NATS identity", key, d.Role)
		}
	}
	return vaultsecret.ValidateRefs(d.Cell, d.Role, d.Secrets, d.Env)
}

func (c *Controller) retired(ctx context.Context, node string) (bool, error) {
	mark, _, err := c.readRetirement(ctx, node)
	return mark.Retired, err
}

func (c *Controller) markRetired(ctx context.Context, epoch uint64, node string, retired bool) error {
	if err := c.guard(ctx, epoch); err != nil {
		return err
	}
	data, operation, err := mutationPayload(retirement{Retired: retired})
	if err != nil {
		return err
	}
	for range 8 {
		mark, revision, err := c.readRetirement(ctx, node)
		if err != nil {
			return err
		}
		if mark.Retired == retired {
			return nil
		}
		_, err = c.mutations.CommitHostMutation(ctx, epoch, authority.MutationRetirement, registrationSubjectKey(c.cell, node), operation, revision, data)
		if err == nil {
			return nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return fmt.Errorf("mark %s retired=%t: %w", node, retired, err)
		}
	}
	return errors.New("host retirement contention")
}

func (c *Controller) Unretire(ctx context.Context, node string) error {
	c.retireMu.Lock()
	defer c.retireMu.Unlock()
	return c.markRetired(ctx, c.authorityEpoch(), node, false)
}

// Cordon retires node whatever it holds: a cordoned host takes no new allocation and the workload reconciler moves its replicas elsewhere.
func (c *Controller) Cordon(ctx context.Context, node string) error {
	c.retireMu.Lock()
	defer c.retireMu.Unlock()
	return c.markRetired(ctx, c.authorityEpoch(), node, true)
}

func (c *Controller) controlLogSubjects(ctx context.Context, filter string) (*jetstream.StreamInfo, error) {
	if err := c.lockControlLog(ctx); err != nil {
		return nil, err
	}
	defer func() { <-c.controlLogInfoGate }()
	return c.controlLog.Info(ctx, jetstream.WithSubjectFilter(filter))
}

func (c *Controller) lockControlLog(ctx context.Context) error {
	c.controlLogInfoOnce.Do(func() { c.controlLogInfoGate = make(chan struct{}, 1) })
	if err := ctx.Err(); err != nil {
		return err
	}
	select {
	case c.controlLogInfoGate <- struct{}{}:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (c *Controller) ListHosts(ctx context.Context) ([]HostStatus, error) {
	if c.controlLog == nil {
		return nil, errors.New("ordered control log is required for host discovery")
	}
	prefix := protocol.Control(c.cell, "host", "registration", c.cell) + "."
	info, err := c.controlLogSubjects(ctx, prefix+"*")
	if err != nil {
		return nil, err
	}
	var hosts []HostStatus
	for subject := range info.State.Subjects {
		node, ok := strings.CutPrefix(subject, prefix)
		if !ok || validateToken(node, "node") != nil {
			return nil, errors.New("host registration subject is invalid")
		}
		r, registrationRevision, exists, err := c.readRegistration(ctx, node)
		if err != nil {
			return nil, err
		} else if !exists {
			continue
		}
		retirement, retirementRevision, err := c.readRetirement(ctx, node)
		if err != nil {
			return nil, err
		}
		status := HostStatus{Registration: r, Retired: retirement.Retired, Verified: !c.readOnly}
		s, _, exists, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
		if err != nil {
			return nil, err
		}
		if exists && s.RegistrationGeneration == r.Generation && time.Now().Before(s.ExpiresAt) {
			status.SessionExpiresAt = s.ExpiresAt
			for _, role := range r.Roles {
				report, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil {
					return nil, err
				}
				if !ok || report.Cell != c.cell || report.Node != r.Node || report.Environment != r.Environment || report.Role != role ||
					report.SessionID != s.SessionID || report.Epoch != s.Epoch || time.Since(report.ObservedAt) >= ReportMaxAge || report.ObservedAt.After(time.Now().Add(maxClockSkew)) {
					continue
				}
				desired, desiredRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil {
					return nil, err
				}
				if !ok || report.Generation != desired.Generation || report.Digest != desired.Digest || desired.Withdrawn && report.State == "running" ||
					validateManagedReportForDesired(report, desired) != nil {
					continue
				}
				confirmed, confirmedRevision, ok, err := c.readDesired(ctx, r.Node, role)
				if err != nil || !ok || confirmedRevision != desiredRevision || !sameJSON(confirmed, desired) {
					return nil, errors.New("desired changed during host status read")
				}
				check, _, ok, err := c.reportSnapshot(ctx, reportKey(c.cell, r.Node, role))
				if err != nil || !ok || check.ObservedAt.Before(report.ObservedAt) || !sameReportMeaning(check, report) ||
					check.SessionID != s.SessionID || check.Epoch != s.Epoch || check.Generation != desired.Generation || check.Digest != desired.Digest ||
					validateManagedReportForDesired(check, desired) != nil ||
					time.Since(check.ObservedAt) >= ReportMaxAge || check.ObservedAt.After(time.Now().Add(maxClockSkew)) || desired.Withdrawn && check.State == "running" {
					return nil, errors.New("report changed during host status read")
				}
				status.Reports = append(status.Reports, check)
			}
			check, _, ok, err := c.sessionSnapshot(ctx, sessionKey(c.cell, r.Node))
			if err != nil || !ok || check.RegistrationGeneration != r.Generation || check.SessionID != s.SessionID || check.Epoch != s.Epoch || !time.Now().Before(check.ExpiresAt) {
				return nil, errors.New("session changed during host status read")
			}
			status.SessionExpiresAt = check.ExpiresAt
		}
		confirmed, confirmedRevision, ok, err := c.readRegistration(ctx, node)
		if err != nil || !ok || confirmedRevision != registrationRevision || !sameJSON(confirmed, r) {
			return nil, errors.New("registration changed during host status read")
		}
		if _, revision, err := c.readRetirement(ctx, node); err != nil || revision != retirementRevision {
			return nil, errors.New("retirement changed during host status read")
		}
		hosts = append(hosts, status)
	}
	slices.SortFunc(hosts, func(a, b HostStatus) int { return strings.Compare(a.Registration.Node, b.Registration.Node) })
	return hosts, nil
}

func sameReportMeaning(a, b Report) bool {
	a.ObservedAt = time.Time{}
	b.ObservedAt = time.Time{}
	if a.Managed != nil && a.Managed.ServingProof != nil {
		managed, proof := *a.Managed, *a.Managed.ServingProof
		proof.Nonce = ""
		managed.ServingProof = &proof
		a.Managed = &managed
	}
	if b.Managed != nil && b.Managed.ServingProof != nil {
		managed, proof := *b.Managed, *b.Managed.ServingProof
		proof.Nonce = ""
		managed.ServingProof = &proof
		b.Managed = &managed
	}
	return sameJSON(a, b)
}

func (c *Controller) ListDesired(ctx context.Context, role string) ([]Desired, error) {
	if c == nil || c.controlLog == nil || c.mutations == nil {
		return nil, errors.New("ordered host state reader is unavailable")
	}
	if role != "" {
		if err := validateToken(role, "role"); err != nil {
			return nil, err
		}
	}
	prefix := protocol.Control(c.cell, "host", "desired", c.cell) + "."
	filter := prefix + ">"
	if role != "" {
		filter = prefix + "*." + role
	}
	info, err := c.controlLogSubjects(ctx, filter)
	if err != nil {
		return nil, err
	}
	var result []Desired
	for subject := range info.State.Subjects {
		suffix, ok := strings.CutPrefix(subject, prefix)
		if !ok {
			return nil, errors.New("desired log subject has unexpected prefix")
		}
		node, roleName, ok := strings.Cut(suffix, ".")
		if !ok || validateToken(node, "node") != nil || validateToken(roleName, "role") != nil || strings.Contains(roleName, ".") {
			return nil, errors.New("desired log subject is malformed")
		}
		if role != "" && roleName != role {
			continue
		}
		d, revision, exists, err := c.readDesired(ctx, node, roleName)
		if err != nil {
			return nil, err
		}
		if !exists || revision == 0 {
			return nil, errors.New("desired log index is inconsistent")
		}
		result = append(result, d)
	}
	slices.SortFunc(result, func(a, b Desired) int {
		if a.Node < b.Node {
			return -1
		}
		if a.Node > b.Node {
			return 1
		}
		return strings.Compare(a.Role, b.Role)
	})
	return result, nil
}

func registrationSubjectKey(cell, node string) string  { return cell + "." + node }
func desiredSubjectKey(cell, node, role string) string { return cell + "." + node + "." + role }

func rejectObsoleteRetirementState(ctx context.Context, state jetstream.KeyValue, cell string) error {
	keys, err := state.ListKeysFiltered(ctx, "retired."+cell+".>", "retirement-quarantine."+cell+".>", "retirement-cutover."+cell)
	if err != nil {
		return fmt.Errorf("validate host retirement storage: %w", err)
	}
	defer keys.Stop()
	obsolete := false
	for range keys.Keys() {
		obsolete = true
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if obsolete {
		return errors.New("host state contains obsolete retirement keys; updated host control cannot start over this state")
	}
	return nil
}

func (c *Controller) readRetirement(ctx context.Context, node string) (retirement, uint64, error) {
	if err := validateToken(node, "node"); err != nil {
		return retirement{}, 0, err
	}
	key := registrationSubjectKey(c.cell, node)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationRetirement, key)
	if errors.Is(err, authority.ErrNotFound) {
		return retirement{}, 0, nil
	}
	if err != nil {
		return retirement{}, 0, err
	}
	if entry.Kind != authority.MutationRetirement || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return retirement{}, 0, errors.New("retirement log entry is malformed")
	}
	mark, err := decodeRetirement(entry.Payload)
	if err != nil {
		return retirement{}, 0, err
	}
	return mark, entry.Sequence, nil
}

func decodeRetirement(payload []byte) (retirement, error) {
	var value struct {
		Retired *bool `json:"retired"`
	}
	if err := decodeStrict(payload, &value); err != nil {
		return retirement{}, err
	}
	if value.Retired == nil {
		return retirement{}, errors.New("retirement record requires a non-null retired state")
	}
	return retirement{Retired: *value.Retired}, nil
}

func (c *Controller) readRegistration(ctx context.Context, node string) (Registration, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Registration{}, 0, false, err
	}
	key := registrationSubjectKey(c.cell, node)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationRegistration, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Registration{}, 0, false, nil
	}
	if err != nil {
		return Registration{}, 0, false, err
	}
	if entry.Kind != authority.MutationRegistration || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Registration{}, 0, false, errors.New("registration log entry is malformed")
	}
	var r Registration
	if err := decodeStrict(entry.Payload, &r); err != nil {
		return Registration{}, 0, false, err
	}
	if r.Node != node || r.ID != entityid.Derive("host", c.cell, node) {
		return Registration{}, 0, false, errors.New("registration log identity mismatch")
	}
	if err := validateRegistration(r, c.cell); err != nil {
		return Registration{}, 0, false, err
	}
	return r, entry.Sequence, true, nil
}

func (c *Controller) readDesired(ctx context.Context, node, role string) (Desired, uint64, bool, error) {
	if err := validateToken(node, "node"); err != nil {
		return Desired{}, 0, false, err
	}
	if err := validateToken(role, "role"); err != nil {
		return Desired{}, 0, false, err
	}
	key := desiredSubjectKey(c.cell, node, role)
	entry, err := c.mutations.ReadHostMutation(ctx, authority.MutationDesired, key)
	if errors.Is(err, authority.ErrNotFound) {
		return Desired{}, 0, false, nil
	}
	if err != nil {
		return Desired{}, 0, false, err
	}
	if entry.Kind != authority.MutationDesired || entry.SubjectKey != key || entry.Sequence == 0 || entry.Epoch == 0 {
		return Desired{}, 0, false, errors.New("desired log entry is malformed")
	}
	var d Desired
	if err := decodeStrict(entry.Payload, &d); err != nil {
		return Desired{}, 0, false, err
	}
	if d.Cell != c.cell || d.Node != node || d.Role != role || d.AuthorityEpoch != entry.Epoch {
		return Desired{}, 0, false, errors.New("desired log identity or epoch mismatch")
	}
	return d, entry.Sequence, true, nil
}

func mutationPayload(value any) ([]byte, string, error) {
	data, err := json.Marshal(value)
	if err != nil {
		return nil, "", err
	}
	if len(data) > 64<<10 {
		return nil, "", errors.New("host mutation exceeds value limit")
	}
	hash := sha256.Sum256(data)
	return data, entityid.Derive("host-mutation", hex.EncodeToString(hash[:])), nil
}

func (c *Controller) serveCycle(ctx context.Context, req request, r Registration, s session) (any, error) {
	var query cycleQuery
	if err := decodeStrict(req.Payload, &query); err != nil {
		return nil, err
	}
	if !slices.Contains(r.Roles, query.Role) || validateDigest(query.Digest) != nil || query.Generation == 0 || query.AuthorityEpoch == 0 || !entityid.Valid(query.Attempt) {
		return nil, errors.New("invalid cycle query")
	}
	var desired Desired
	if query.CycleID == "" {
		var exists bool
		var err error
		desired, _, exists, err = c.readDesired(ctx, req.Node, query.Role)
		if err != nil {
			return nil, err
		}
		if !exists || desired.Withdrawn || desired.Generation != query.Generation || desired.AuthorityEpoch != query.AuthorityEpoch || desired.Digest != query.Digest {
			return nil, errors.New("cycle target is no longer desired")
		}
	}
	key := cycleKey(c.cell, req.Node, query.Role)
	// granted remembers the restart gate's grant across CAS retries, so one
	// request asks the gate at most once.
	granted := false
	for range 8 {
		var old cycleRecord
		revision, exists, err := c.get(ctx, key, &old)
		if err != nil {
			return nil, err
		}
		if req.Operation != "cycle" {
			return nil, errors.New("invalid cycle operation")
		}
		if query.CycleID == "" {
			if exists && old.Generation > query.Generation {
				return nil, errors.New("cycle generation moved backward")
			}
			if exists && old.Attempt == query.Attempt && old.Digest == query.Digest && old.Generation == query.Generation && old.AuthorityEpoch == query.AuthorityEpoch && old.SessionID == s.SessionID && old.Epoch == s.Epoch {
				if _, err := c.cas(ctx, key, old, revision); err == nil {
					return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: old.State, NotBefore: old.NotBefore}, nil
				} else if casConflict(err) {
					continue
				} else {
					return nil, err
				}
			}
			if exists && old.State == "active" && old.Generation == query.Generation && old.AuthorityEpoch == query.AuthorityEpoch && old.SessionID == s.SessionID && old.Epoch == s.Epoch {
				return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: "busy"}, nil
			}
			if exists && old.State == "active" && old.Digest == query.Digest && old.Generation == query.Generation && old.AuthorityEpoch == query.AuthorityEpoch {
				abandoned := old
				abandoned.State = "failed"
				abandoned.Failures = min(old.Failures+1, 6)
				abandoned.NotBefore = time.Now().Add(backoffDuration(abandoned.Failures))
				if _, err := c.cas(ctx, key, abandoned, revision); err == nil {
					return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: "backoff", NotBefore: abandoned.NotBefore}, nil
				} else if casConflict(err) {
					continue
				} else {
					return nil, err
				}
			}
			if exists && old.Digest == query.Digest && old.Generation == query.Generation && old.AuthorityEpoch == query.AuthorityEpoch && time.Now().Before(old.NotBefore) {
				return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: "backoff", NotBefore: old.NotBefore}, nil
			}
			// Only opening a new cycle is gated: the agent's revalidation
			// resolves the cycle it already holds above. Managed members stop
			// their workload before they ask, so they are never held; their
			// drain receipts order their restarts.
			if c.restartGate != nil && desired.ManagedMember == nil && !granted {
				ok, err := c.restartGate(ctx, req.Node, desired)
				if err != nil {
					return nil, err
				}
				if !ok {
					return cycleReply{State: "held"}, nil
				}
				granted = true
			}
			id, err := randomID()
			if err != nil {
				return nil, err
			}
			next := cycleRecord{CycleID: id, Fence: 1, Attempt: query.Attempt, Digest: query.Digest, Generation: query.Generation, AuthorityEpoch: query.AuthorityEpoch, SessionID: s.SessionID, Epoch: s.Epoch, State: "active"}
			if exists {
				if old.Fence == ^uint64(0) {
					return nil, errors.New("cycle fence exhausted")
				}
				next.Fence = old.Fence + 1
				if old.Digest == query.Digest && old.Generation == query.Generation && old.AuthorityEpoch == query.AuthorityEpoch {
					next.Failures = old.Failures
				}
			}
			if _, err := c.cas(ctx, key, next, revision); err == nil {
				return cycleReply{CycleID: id, Fence: next.Fence, State: "active"}, nil
			} else if casConflict(err) {
				continue
			} else {
				return nil, err
			}
		}
		if !exists || old.CycleID != query.CycleID || old.Fence != query.Fence || old.Attempt != query.Attempt || old.SessionID != s.SessionID || old.Epoch != s.Epoch || old.Digest != query.Digest || old.Generation != query.Generation || old.AuthorityEpoch != query.AuthorityEpoch {
			return nil, errors.New("cycle outcome fence mismatch")
		}
		if old.State != "active" {
			return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: old.State, NotBefore: old.NotBefore}, nil
		}
		next := old
		if query.Succeeded {
			next.State = "succeeded"
			next.Failures = 0
		} else {
			next.State = "failed"
			next.Failures = min(old.Failures+1, 6)
			next.NotBefore = time.Now().Add(backoffDuration(next.Failures))
		}
		if _, err := c.cas(ctx, key, next, revision); err == nil {
			return cycleReply{CycleID: old.CycleID, Fence: old.Fence, State: next.State, NotBefore: next.NotBefore}, nil
		} else if casConflict(err) {
			continue
		} else {
			return nil, err
		}
	}
	return nil, errors.New("cycle contention")
}

func (c *Controller) storeReport(ctx context.Context, req request, r Registration, s session) (any, error) {
	var report Report
	if err := decodeStrict(req.Payload, &report); err != nil {
		return nil, err
	}
	if report.Cell != c.cell || report.Node != req.Node || report.Environment != r.Environment || !slices.Contains(r.Roles, report.Role) || report.SessionID != s.SessionID || report.Epoch != s.Epoch ||
		report.ObservedAt.Before(req.IssuedAt.Add(-30*time.Second)) || report.ObservedAt.After(time.Now().Add(maxClockSkew)) || report.ObservedAt.IsZero() || len(report.Error) > 1024 || len(report.State) > 64 {
		return nil, errors.New("report identity or timestamp mismatch")
	}
	desired, _, exists, err := c.readDesired(ctx, req.Node, report.Role)
	if err != nil {
		return nil, err
	}
	if !exists || report.Generation != desired.Generation || report.Digest != desired.Digest {
		return nil, errors.New("report target is not current")
	}
	if err := validateManagedReportForDesired(report, desired); err != nil {
		return nil, err
	}
	key := reportKey(c.cell, req.Node, report.Role)
	for range 8 {
		current, _, exists, err := c.readDesired(ctx, req.Node, report.Role)
		if err != nil || !exists || !sameJSON(current, desired) {
			return nil, errors.New("desired changed before report commit")
		}
		if _, _, err := c.authorize(ctx, req); err != nil {
			return nil, err
		}
		var old Report
		revision, exists, err := c.get(ctx, key, &old)
		if err != nil {
			return nil, err
		}
		if exists {
			if report.Generation < old.Generation || report.Generation == old.Generation && report.ObservedAt.Before(old.ObservedAt) {
				return nil, errors.New("report ordering moved backward")
			}
			if report.Generation == old.Generation && report.ObservedAt.Equal(old.ObservedAt) && !sameJSON(report, old) {
				return nil, errors.New("report timestamp collision")
			}
		}
		_, err = c.cas(ctx, key, report, revision)
		if err == nil {
			current, _, exists, checkErr := c.readDesired(ctx, req.Node, report.Role)
			if checkErr != nil || !exists || !sameJSON(current, desired) {
				return nil, errors.New("desired changed during report commit")
			}
			return struct {
				Accepted bool `json:"accepted"`
			}{true}, nil
		}
		if !casConflict(err) {
			return nil, fmt.Errorf("store report: %w", err)
		}
	}
	return nil, errors.New("report contention")
}

func (a *Agent) reconcile(ctx context.Context, role string) (resultErr error) {
	if a.sessionLost.Load() {
		return errors.New("host session was lost")
	}
	if _, _, err := a.executionLease(); err != nil {
		return err
	}
	if _, err := a.fenceTerraBaseMember(ctx, role); err != nil {
		return err
	}
	pending, hasPending := a.pending[role]
	if hasPending && pending.outcomeReady {
		if err := a.flushCycle(ctx, role); err != nil {
			return err
		}
		hasPending = false
	}
	var target desiredReply
	if err := a.request(ctx, "desired", struct {
		Role string `json:"role"`
	}{role}, &target); err != nil {
		return errors.Join(err, a.revokeManagedNativeRoot(role))
	}
	if err := a.validateDesiredReply(target); err != nil {
		return errors.Join(err, a.revokeManagedNativeRoot(role))
	}
	if target.Desired == nil {
		if err := a.revokeManagedNativeRoot(role); err != nil {
			return err
		}
		if hasPending {
			if err := a.failPendingCycle(ctx, role); err != nil {
				return err
			}
		}
		return nil
	}
	d := *target.Desired
	if d.Cell != a.cfg.Cell || d.Node != a.cfg.Node || d.Environment != a.cfg.Environment || d.Role != role || d.Generation == 0 {
		return errors.Join(errors.New("desired identity mismatch"), a.revokeManagedNativeRoot(role))
	}
	if err := validateDesired(d, a.cfg.Cell, *target.Registration); err != nil {
		return errors.Join(err, a.revokeManagedNativeRoot(role))
	}
	if !d.Withdrawn && d.ManagedMember != nil {
		fingerprint, err := desiredFingerprint(d)
		if err != nil {
			return errors.Join(err, a.revokeManagedNativeRoot(role))
		}
		if err := a.pinManagedNativeRootDesired(role, fingerprint); err != nil {
			return errors.Join(err, a.revokeManagedNativeRoot(role))
		}
		if err := a.stopManagedNativeRootIfChanged(role, fingerprint); err != nil {
			return err
		}
	}
	if hasPending && (d.Withdrawn || d.Generation != pending.query.Generation || d.Digest != pending.query.Digest || d.AuthorityEpoch != pending.query.AuthorityEpoch) {
		if err := a.failPendingCycle(ctx, role); err != nil {
			return err
		}
		hasPending = false
	}
	backupObserved := false
	defer func() {
		if resultErr != nil && !backupObserved && !errors.Is(resultErr, errSessionContention) {
			_ = a.publishReport(ctx, a.reportFor(d, "failed", resultErr))
		}
	}()
	if d.Withdrawn {
		if err := a.revokeManagedNativeRoot(role); err != nil {
			return err
		}
		if err := a.runner.Stop(ctx, role); err != nil {
			return err
		}
		return a.publishReport(ctx, a.reportFor(d, "stopped", nil))
	}
	if err := validateDigest(d.Digest); err != nil {
		return err
	}
	if d.ManagedMember != nil {
		if d.ManagedMember.Runtime != nil && a.cfg.ManagedRuntimeRoot != "" {
			backup, err := a.fetchManagedBackupCommand(ctx, role)
			if err != nil {
				return err
			}
			if backup.Pending {
				current, err := a.runner.Observe(ctx, role)
				if err != nil {
					return err
				}
				if !current.Running {
					err := a.reconcileManaged(ctx, d, target, true)
					backupObserved = err == nil
					return err
				}
				var operationErr error
				if backup.Command != nil {
					operationErr = a.reconcileManagedBackup(ctx, d, *target.Registration, *backup.Command)
				}
				reportErr := a.reportManagedBackupProcess(ctx, d, nil)
				backupObserved = reportErr == nil
				return errors.Join(operationErr, reportErr)
			}
			command, err := a.fetchManagedDrainCommand(ctx, role)
			if err != nil {
				return err
			}
			if command != nil {
				return a.reconcileManagedDrain(ctx, d, *target.Registration, *command)
			}
		}
		return a.reconcileManaged(ctx, d, target, false)
	}
	if err := a.revokeManagedNativeRoot(role); err != nil {
		return err
	}
	fingerprint, err := desiredFingerprint(d)
	if err != nil {
		return err
	}
	current, err := a.runner.Observe(ctx, role)
	if err != nil {
		return err
	}
	if (a.terraBaseMember(d) || a.tsAuthReplica(d)) && a.terraBaseExited(current, d, fingerprint) {
		return errors.New(role + " exited; it is relaunched on the next poll")
	}
	// A running workload renews its identity on every pass, held or not, so
	// it cannot expire while a release waits behind a restart hold (TS-803).
	var filesErr error
	if current.Running {
		filesErr = a.refreshRoleFiles(ctx, d)
	}
	if current.Running && current.Digest == d.Digest && current.Fingerprint == fingerprint {
		if hasPending {
			pending.query.Succeeded = true
			pending.outcomeReady = true
			a.pending[role] = pending
			if err := a.flushCycle(ctx, role); err != nil {
				return err
			}
		}
		report := a.reportFor(d, "running", nil)
		if a.terraBaseMember(d) {
			report = a.terraBaseRunningReport(ctx, d)
		} else if a.tsAuthReplica(d) {
			report = a.tsAuthRunningReport(ctx, d)
		}
		if filesErr != nil {
			report.Error = strings.TrimPrefix(report.Error+"; "+filesErr.Error(), "; ")
		}
		return a.publishReport(ctx, report)
	}
	var query cycleQuery
	var cycle cycleReply
	if hasPending {
		query = pending.query
		cycle = cycleReply{CycleID: query.CycleID, Fence: query.Fence, State: "active"}
	} else {
		if current.Running && a.restartHeld(d) {
			return a.publishReport(ctx, a.reportFor(d, "waiting", filesErr))
		}
		attempt, err := randomID()
		if err != nil {
			return err
		}
		query = cycleQuery{Role: role, Digest: d.Digest, Generation: d.Generation, AuthorityEpoch: d.AuthorityEpoch, Attempt: attempt}
		if err := a.request(ctx, "cycle", query, &cycle); err != nil {
			return err
		}
		if cycle.State == "held" {
			// The running workload keeps serving until the controller
			// grants the restart (a TerraBase seat waits for its drain).
			return a.publishReport(ctx, a.reportFor(d, "waiting", filesErr))
		}
		if cycle.State != "active" {
			return nil
		}
		query.CycleID = cycle.CycleID
		query.Fence = cycle.Fence
		a.pending[role] = pendingCycle{query: query}
	}
	cycleSucceeded := false
	defer func() {
		if resultErr != nil && !cycleSucceeded && !errors.Is(resultErr, errSessionContention) {
			pending := a.pending[role]
			pending.query.Succeeded = false
			pending.outcomeReady = true
			a.pending[role] = pending
			if ctx.Err() != nil || a.sessionLost.Load() {
				return
			}
			finishCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()
			_ = a.flushCycle(finishCtx, role)
		}
	}()
	executable, err := a.fetchArtifact(ctx, role, d.Digest)
	if err != nil {
		return err
	}
	workload := Workload{Role: role, Digest: d.Digest, Fingerprint: fingerprint, Executable: executable, Args: d.Args, Env: d.Env,
		CgroupMemoryMaxBytes: a.cfg.RoleMemoryMaxBytes[role]}
	if a.tsAuthMisplaced(d) {
		return errors.New("ts-auth needs ts_auth_root on this host for its bundle directory and readiness probe")
	}
	secrets, err := a.resolveSecrets(ctx, d)
	if err != nil {
		return err
	}
	roleEnv, err := a.prepareRoleFiles(ctx, d, secrets)
	if err != nil {
		return err
	}
	if len(secrets) != 0 {
		workload.Env = maps.Clone(d.Env)
		if workload.Env == nil {
			workload.Env = map[string]string{}
		}
		maps.Copy(workload.Env, secrets)
	}
	started, certificateExpiry := "running", time.Time{}
	if a.terraBaseMember(d) {
		if workload.Env, certificateExpiry, err = a.prepareTerraBase(ctx, d); err != nil {
			return err
		}
		workload.DrainTimeout, started = terraBaseDrain, "starting"
	}
	if a.tsAuthReplica(d) {
		if workload.Env, err = a.prepareTSAuth(d, secrets); err != nil {
			return err
		}
		workload.DrainTimeout, started = tsAuthDrain, "starting"
	}
	if len(roleEnv) != 0 {
		workload.Env = maps.Clone(workload.Env)
		if workload.Env == nil {
			workload.Env = map[string]string{}
		}
		maps.Copy(workload.Env, roleEnv)
	}
	var latest desiredReply
	if err := a.request(ctx, "desired", struct {
		Role string `json:"role"`
	}{role}, &latest); err != nil {
		return err
	}
	if err := a.validateDesiredReply(latest); err != nil {
		return err
	}
	if !sameDesiredReplyBinding(target, latest) {
		return errors.New("desired target changed before native apply")
	}
	var active cycleReply
	if err := a.request(ctx, "cycle", cycleQuery{Role: role, Digest: d.Digest, Generation: d.Generation, AuthorityEpoch: d.AuthorityEpoch, Attempt: query.Attempt}, &active); err != nil {
		return err
	}
	if active.State != "active" || active.CycleID != cycle.CycleID || active.Fence != cycle.Fence {
		return errors.New("cycle fence changed before native apply")
	}
	if _, _, err := a.executionLease(); err != nil {
		return err
	}
	// The controller requests above took time: launch only on the
	// confirmed filesystem's mount as it is now.
	if a.terraBaseMember(d) && a.cfg.TerraBaseDataVolume {
		if err := a.terraBaseDataVolumeIntact(); err != nil {
			a.terraBaseVolumeConfirmed = ""
			return fmt.Errorf("terrabase data volume changed before launch: %w", err)
		}
	}
	if err := a.runner.Apply(ctx, workload); err != nil {
		return err
	}
	if !certificateExpiry.IsZero() {
		a.terraBase[role] = terraBaseMember{certificateExpiry: certificateExpiry}
	}
	observed, err := a.runner.Observe(ctx, role)
	if err != nil {
		return err
	}
	if !observed.Running || observed.Digest != d.Digest || observed.Fingerprint != fingerprint {
		return errors.New("native workload did not start")
	}
	cycleSucceeded = true
	pending = a.pending[role]
	pending.query.Succeeded = true
	pending.outcomeReady = true
	a.pending[role] = pending
	if err := a.flushCycle(ctx, role); err != nil {
		return err
	}
	if err := a.publishReport(ctx, a.reportFor(d, started, nil)); err != nil {
		return err
	}
	return nil
}

func sameDesiredReplyBinding(first, latest desiredReply) bool {
	return first.Desired != nil && latest.Desired != nil && first.Registration != nil && latest.Registration != nil &&
		first.Revision == latest.Revision && first.RegistrationRevision == latest.RegistrationRevision &&
		sameJSON(*first.Registration, *latest.Registration) && sameJSON(*first.Desired, *latest.Desired)
}

func (a *Agent) validateDesiredReply(reply desiredReply) error {
	if len(a.cfg.Identity) != ed25519.PrivateKeySize {
		return errors.New("agent host identity key is invalid")
	}
	a.mu.RLock()
	generation := a.session.RegistrationGeneration
	a.mu.RUnlock()
	if reply.Registration == nil || reply.RegistrationRevision == 0 ||
		reply.Registration.Generation != generation ||
		reply.Registration.Cell != a.cfg.Cell || reply.Registration.Node != a.cfg.Node ||
		reply.Registration.Environment != a.cfg.Environment ||
		reply.Registration.PublicKey != base64.StdEncoding.EncodeToString(a.cfg.Identity.Public().(ed25519.PublicKey)) {
		return errors.New("desired reply registration differs from host session")
	}
	return validateRegistration(*reply.Registration, a.cfg.Cell)
}

func (a *Agent) resolveSecrets(ctx context.Context, d Desired) (map[string]string, error) {
	if len(d.Secrets) == 0 {
		return nil, nil
	}
	if a.cfg.SecretResolver == nil {
		return nil, errors.New(d.Role + " needs Vault secrets, which this host cannot read")
	}
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()
	values, err := a.cfg.SecretResolver(ctx, d.Secrets)
	if err != nil {
		return nil, err
	}
	// Exactly the named secrets, so a resolver never adds another.
	for key := range d.Secrets {
		if _, ok := values[key]; !ok {
			return nil, fmt.Errorf("Vault secret %s was not read", key)
		}
	}
	if len(values) != len(d.Secrets) {
		return nil, errors.New("Vault secret resolver returned secrets the desired does not name")
	}
	return values, nil
}

func desiredFingerprint(d Desired) (string, error) {
	d.AuthorityEpoch = 0
	data, err := json.Marshal(d)
	if err != nil {
		return "", err
	}
	hash := sha256.Sum256(data)
	return hex.EncodeToString(hash[:]), nil
}

func (a *Agent) flushCycle(ctx context.Context, role string) error {
	pending, ok := a.pending[role]
	if !ok || !pending.outcomeReady {
		return nil
	}
	query := pending.query
	var result cycleReply
	if err := a.request(ctx, "cycle", query, &result); err != nil {
		return err
	}
	expected := "failed"
	if query.Succeeded {
		expected = "succeeded"
	}
	if result.CycleID != query.CycleID || result.Fence != query.Fence || result.State != expected {
		return errors.New("cycle outcome receipt mismatch")
	}
	delete(a.pending, role)
	return nil
}

func (a *Agent) failPendingCycle(ctx context.Context, role string) error {
	pending := a.pending[role]
	pending.query.Succeeded = false
	pending.outcomeReady = true
	a.pending[role] = pending
	return a.flushCycle(ctx, role)
}

func (a *Agent) reportFor(d Desired, state string, failure error) Report {
	a.mu.RLock()
	s := a.session
	a.mu.RUnlock()
	r := Report{Cell: a.cfg.Cell, Node: a.cfg.Node, Environment: a.cfg.Environment, Role: d.Role, Digest: d.Digest, Generation: d.Generation, SessionID: s.SessionID, Epoch: s.Epoch, State: state, ObservedAt: time.Now().UTC()}
	if failure != nil {
		r.Error = failure.Error()
	}
	return r
}

func (a *Agent) publishReport(ctx context.Context, r Report) error {
	a.mu.RLock()
	s := a.session
	a.mu.RUnlock()
	r.SessionID = s.SessionID
	r.Epoch = s.Epoch
	if r.Error != "" && len(r.Error) > 1024 {
		r.Error = r.Error[:1024]
	}
	var ack struct {
		Accepted bool `json:"accepted"`
	}
	if err := a.request(ctx, "report", r, &ack); err != nil {
		return err
	}
	if !ack.Accepted {
		return errors.New("report was not accepted")
	}
	return nil
}

func (a *Agent) terraBaseMember(d Desired) bool {
	return a.cfg.TerraBaseRoot != "" && d.Role == terrabase.Role && d.ManagedMember == nil && !d.Withdrawn
}

func (a *Agent) fenceTerraBaseMember(ctx context.Context, role string) (stopped bool, err error) {
	if !a.cfg.TerraBaseDataVolume || role != terrabase.Role {
		return false, nil
	}
	lost := a.terraBaseDataVolumeIntact()
	if lost == nil {
		return false, nil
	}
	a.terraBaseVolumeConfirmed = ""
	current, observeErr := a.runner.Observe(ctx, role)
	if observeErr == nil && !current.Running {
		return false, nil
	}
	if err := a.runner.Stop(ctx, role); err != nil {
		return false, errors.Join(fmt.Errorf("stop the terrabase member: data volume: %w", lost), observeErr, err)
	}
	delete(a.terraBase, role)
	slog.WarnContext(ctx, "terrabase member stopped: its data volume is not intact", "error", lost)
	return true, nil
}

func (a *Agent) prepareRoleFiles(ctx context.Context, d Desired, secrets map[string]string) (map[string]string, error) {
	files := map[string]string{}
	for key, value := range secrets {
		if vaultsecret.FileKey(key) {
			files[key] = value
			delete(secrets, key)
		}
	}
	grant, granted := roleidentity.Grants[d.Role]
	if len(files) == 0 && (!granted || a.cfg.ManagedRuntimeRoot == "") {
		return nil, nil
	}
	dir, err := a.ensureRoleDir(d.Role)
	if err != nil {
		return nil, err
	}
	env := map[string]string{}
	if err := a.writeSecretFiles(dir, files); err != nil {
		return nil, err
	}
	for key := range files {
		env[key] = filepath.Join(dir, strings.ToLower(key))
	}
	if granted {
		_ = a.ensureRoleIdentity(ctx, d.Role, dir)
		if _, current := roleIdentityExpiry(dir); current {
			env[grant.EnvPrefix+"URL"] = a.cfg.NATSURL
			env[grant.EnvPrefix+"CREDENTIALS_FILE"] = filepath.Join(dir, "nats.creds")
			env[grant.EnvPrefix+"CERTIFICATE"] = filepath.Join(dir, "nats.pem")
			env[grant.EnvPrefix+"PRIVATE_KEY"] = filepath.Join(dir, "nats.key")
			env[grant.EnvPrefix+"CA"] = filepath.Join(dir, "nats-ca.pem")
		}
	}
	return env, nil
}

func (a *Agent) refreshRoleFiles(ctx context.Context, d Desired) error {
	fileRefs := maps.Clone(d.Secrets)
	maps.DeleteFunc(fileRefs, func(key string, _ vaultsecret.Ref) bool { return !vaultsecret.FileKey(key) })
	_, granted := roleidentity.Grants[d.Role]
	if len(fileRefs) == 0 && (!granted || a.cfg.ManagedRuntimeRoot == "") {
		return nil
	}
	if failure, failed := a.roleFilesFailures[d.Role]; failed && time.Since(failure.at) < roleFilesRetry {
		return failure.err
	}
	err := a.renewRoleFiles(ctx, d, fileRefs, granted)
	if a.roleFilesFailures == nil {
		a.roleFilesFailures = map[string]roleFilesFailure{}
	}
	if err != nil {
		// Logged once per distinct error, so a renewal that keeps failing is not silent.
		if previous, failed := a.roleFilesFailures[d.Role]; !failed || previous.err.Error() != err.Error() {
			slog.Warn("role files renewal failed", "component", "roles", "role", d.Role, "error", err)
		}
		a.roleFilesFailures[d.Role] = roleFilesFailure{at: time.Now(), err: err}
	} else {
		delete(a.roleFilesFailures, d.Role)
	}
	return err
}

func (a *Agent) revokeManagedNativeRoot(role string) error {
	a.nativeRootMu.Lock()
	delete(a.nativeDesired, role)
	a.nativeRootMu.Unlock()
	return a.stopManagedNativeRoot(role)
}

func (a *Agent) stopManagedNativeRoot(role string) error {
	a.nativeRootMu.Lock()
	root := a.nativeRoots[role]
	delete(a.nativeRoots, role)
	a.nativeRootMu.Unlock()
	if root == nil {
		return nil
	}
	root.cancel()
	_ = root.listener.Close()
	<-root.done
	return removeManagedNativeRootSocket(root)
}

func (a *Agent) stopAllManagedNativeRoots() error {
	a.nativeRootMu.Lock()
	roles := make([]string, 0, len(a.nativeRoots))
	for role := range a.nativeRoots {
		roles = append(roles, role)
	}
	a.nativeRootMu.Unlock()
	var failures []error
	for _, role := range roles {
		if err := a.stopManagedNativeRoot(role); err != nil {
			failures = append(failures, fmt.Errorf("stop native OCI root helper for %s: %w", role, err))
		}
	}
	return errors.Join(failures...)
}

func signRequest(r *request, key ed25519.PrivateKey, cell string) error {
	if len(key) != ed25519.PrivateKeySize {
		return errors.New("invalid host identity key")
	}
	payload, err := json.Marshal(r)
	if err != nil {
		return err
	}
	r.Envelope, err = protocol.SignEnvelope(payload, protocol.EnvelopeScope{Region: cell, Kind: "host." + r.Operation, Actor: r.Node, OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, r.IssuedAt, r.IssuedAt.Add(requestTTL), key)
	return err
}

func verifyRequest(r request, key ed25519.PublicKey, cell string, now time.Time) error {
	if r.Version != 1 || !lowerHex(r.Nonce, 32) || !entityid.Valid(r.SessionID) || r.IssuedAt.IsZero() || r.IssuedAt.After(now.Add(maxClockSkew)) || now.Sub(r.IssuedAt) >= requestTTL {
		return errors.New("invalid or expired host request")
	}
	if !r.Envelope.IssuedAt.Equal(r.IssuedAt) || r.Envelope.Epoch != r.Epoch {
		return errors.New("host request envelope binding mismatch")
	}
	return protocol.VerifyEnvelope(r.Envelope, protocol.EnvelopeScope{Region: cell, Kind: "host." + r.Operation, Actor: r.Node, OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, key, now, protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew})
}

func decodeStrict(data []byte, destination any) error {
	return protocol.DecodeStrict(data, destination, 512<<10)
}

func exchange(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey, r request, out any) error {
	return exchangeWithEnvelope(ctx, conn, cell, controllerKey, r, out, nil)
}

func exchangeWithEnvelope(ctx context.Context, conn *nats.Conn, cell string, controllerKey ed25519.PublicKey,
	r request, out any, signedOut *protocol.Envelope,
) error {
	if conn == nil {
		return errors.New("NATS connection is required")
	}
	data, err := protocol.EncodeJSON(r.Envelope)
	if err != nil {
		return err
	}
	if len(data) > 64<<10 {
		return errors.New("host request is too large")
	}
	subject, err := protocol.AgentObservationSubject(cell, r.NATSUserPublicKey, r.Operation)
	if err != nil {
		return err
	}
	timeout := 5 * time.Second
	if r.Operation == "material" || r.Operation == "function-material" || r.Operation == "volume-init" || r.Operation == "runtime-effect" || r.Operation == "container-material" || r.Operation == "registry-admission" {
		timeout = 30 * time.Second
	}
	deadline, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	msg, err := conn.RequestMsgWithContext(deadline, &nats.Msg{Subject: subject, Data: data, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return err
	}
	if len(msg.Data) > 512<<10 {
		return errors.New("host response is too large")
	}
	var signed protocol.Envelope
	if err := protocol.DecodeStrict(msg.Data, &signed, 512<<10); err != nil {
		return err
	}
	if err := protocol.VerifyEnvelope(signed, protocol.EnvelopeScope{Region: cell, Kind: "host.response." + r.Operation, Actor: "controller", OperationID: entityid.Derive("host-request", r.Nonce), Epoch: r.Epoch}, controllerKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: requestTTL, ClockSkew: maxClockSkew}); err != nil {
		return err
	}
	var result response
	if err := decodeStrict([]byte(signed.Payload), &result); err != nil {
		return err
	}
	if result.Nonce != r.Nonce || result.Node != r.Node || result.SessionID != r.SessionID || result.Epoch != r.Epoch || result.Operation != r.Operation {
		return errors.New("host response binding mismatch")
	}
	if result.Error != "" {
		if strings.HasPrefix(result.Error, authority.ErrNotLeader.Error()) {
			return fmt.Errorf("%w: %s", errControllerNotLeader, result.Error)
		}
		if result.Retryable {
			if result.Error == errSessionContention.Error() {
				return errSessionContention
			}
			if r.Operation == "session" {
				return fmt.Errorf("%w: %s", errSessionBackendUnavailable, result.Error)
			}
			return errArtifactPreparing
		}
		if r.Operation == "session" {
			if result.Error == errSessionOwned.Error() {
				return errSessionOwned
			}
			return fmt.Errorf("%w: %s", errSessionRequestDenied, result.Error)
		}
		return fmt.Errorf("host request denied: %s", result.Error)
	}
	if out != nil {
		if err := decodeStrict(result.Payload, out); err != nil {
			return err
		}
	}
	if signedOut != nil {
		*signedOut = signed
	}
	return nil
}

func SignEnvelope(
	payload []byte,
	scope EnvelopeScope,
	issuedAt time.Time,
	expiresAt time.Time,
	privateKey ed25519.PrivateKey,
) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: expected an Ed25519 private key", ErrInvalidEnvelope)
	}
	normalized, err := normalizeScope(scope)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validProtocolTime(issuedAt) || !validProtocolTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: issuedAt and expiresAt must form a valid UTC interval", ErrInvalidEnvelope)
	}
	compactPayload, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: EnvelopeSchemaVersion,
		Region:        normalized.Region,
		Kind:          normalized.Kind,
		Actor:         normalized.Actor,
		Generation:    normalized.Generation,
		Epoch:         normalized.Epoch,
		OperationID:   normalized.OperationID,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		KeyID:         keyID,
		Payload:       compactPayload,
	}
	material, err := signedMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

func VerifyEnvelope(
	envelope Envelope,
	expected EnvelopeScope,
	publicKey ed25519.PublicKey,
	now time.Time,
	policy VerifyPolicy,
) error {
	if len(publicKey) != ed25519.PublicKeySize || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 || !validProtocolTime(now) {
		return ErrInvalidPolicy
	}
	if envelope.SchemaVersion != EnvelopeSchemaVersion {
		return fmt.Errorf("%w: unsupported schema version", ErrInvalidEnvelope)
	}
	actualScope, err := normalizeScope(EnvelopeScope{
		Region: envelope.Region, Kind: envelope.Kind, Actor: envelope.Actor,
		OperationID: envelope.OperationID, Generation: envelope.Generation, Epoch: envelope.Epoch,
	})
	if err != nil {
		return err
	}
	expectedScope, err := normalizeScope(expected)
	if err != nil {
		return err
	}
	if actualScope != expectedScope {
		return ErrScopeMismatch
	}
	if !validProtocolTime(envelope.IssuedAt) || !validProtocolTime(envelope.ExpiresAt) ||
		!envelope.ExpiresAt.After(envelope.IssuedAt) ||
		envelope.ExpiresAt.Sub(envelope.IssuedAt) > policy.MaxLifetime {
		return fmt.Errorf("%w: invalid timestamp interval", ErrInvalidEnvelope)
	}
	issuedAt := envelope.IssuedAt.Round(0).UTC()
	expiresAt := envelope.ExpiresAt.Round(0).UTC()
	if issuedAt.Sub(now) > policy.ClockSkew {
		return ErrNotYetValid
	}
	if !now.Before(expiresAt) {
		return ErrExpired
	}
	expectedKeyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if envelope.KeyID != expectedKeyID {
		return ErrKeyMismatch
	}
	compact, err := compactPayload(envelope.Payload)
	if err != nil {
		return err
	}
	envelope.Region = actualScope.Region
	envelope.Kind = actualScope.Kind
	envelope.Actor = actualScope.Actor
	envelope.OperationID = actualScope.OperationID
	envelope.IssuedAt = issuedAt
	envelope.ExpiresAt = expiresAt
	envelope.Payload = compact
	material, err := signedMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := base64.RawURLEncoding.DecodeString(envelope.Signature)
	if err != nil || len(signature) != ed25519.SignatureSize || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

